    [Fact]
    public async Task Every_api_endpoint_declares_an_explicit_authentication_boundary()
    {
        var endpoints = _factory!.Services.GetServices<EndpointDataSource>()
            .SelectMany(source => source.Endpoints)
            .OfType<RouteEndpoint>()
            .Where(endpoint => endpoint.RoutePattern.RawText?.StartsWith("/api", StringComparison.OrdinalIgnoreCase) == true)
            .ToArray();

        Assert.True(endpoints.Length >= 300, $"Expected the complete API endpoint inventory, found {endpoints.Length}.");
        var unprotected = endpoints.Where(endpoint =>
                endpoint.Metadata.GetMetadata<IAllowAnonymous>() is null &&
                !endpoint.Metadata.GetOrderedMetadata<IAuthorizeData>().Any())
            .Select(DescribeEndpoint)
            .OrderBy(value => value, StringComparer.Ordinal)
            .ToArray();
        Assert.True(unprotected.Length == 0,
            "API endpoints need explicit authorization or AllowAnonymous metadata:\n" + string.Join("\n", unprotected));

        var actualPublicRoutes = endpoints
            .Where(endpoint => endpoint.Metadata.GetMetadata<IAllowAnonymous>() is not null)
            .Select(DescribeEndpoint)
            .ToHashSet(StringComparer.Ordinal);
        var expectedPublicRoutes = new HashSet<string>(StringComparer.Ordinal)
        {
            "GET /api/status",
            "GET /api/setup/status",
            "GET /api/session/csrf",
            "GET /api/platform/bootstrap/status",
            "POST /api/setup/initial-owner",
            "POST /api/platform/bootstrap",
            "POST /api/session/login",
            "POST /api/session/password/forgot",
            "POST /api/session/password/reset",
            // Company-required MFA enrollment happens before a session exists; both routes require
            // a CSRF token and a short-lived, single-use, user/company/security-stamp-bound ticket.
            "POST /api/session/company-mfa/setup",
            "POST /api/session/company-mfa/verify",
            "POST /api/checkout/initialize",
            "POST /api/checkout/callback",
            "POST /api/checkout/webhook",
            "GET /api/checkout/status",
            // Trial enrollment starts before a session exists. Writes require CSRF and the
            // checkout rate limit; confirmation additionally requires a short-lived email proof.
            "GET /api/trials/status",
            "POST /api/trials/request",
            "POST /api/trials/confirm",
            // Checkout quote is public so unauthenticated buyers can preview coupon-adjusted pricing.
            "POST /api/checkout/quote",
            "GET /api/plans",
            "GET /api/site-content",
            "POST /api/demo-requests",
            "GET /api/v1",
            "GET /api/v1/accessories",
            "GET /api/v1/assets",
            "POST /api/v1/assets",
            "PUT /api/v1/assets/{id:guid}",
            // Customer API endpoints use explicit bearer-token scope checks inside the handler.
            "PUT /api/v1/assets/{id:guid}/installed-software",
            "GET /api/v1/asset-custom-fields",
            "GET /api/v1/employees"
        };
        Assert.True(expectedPublicRoutes.SetEquals(actualPublicRoutes),
            "Review anonymous API route changes. Unexpected: " +
            string.Join(", ", actualPublicRoutes.Except(expectedPublicRoutes).OrderBy(x => x, StringComparer.Ordinal)) +
            "; missing: " +
            string.Join(", ", expectedPublicRoutes.Except(actualPublicRoutes).OrderBy(x => x, StringComparer.Ordinal)));

        foreach (var trialRoute in new[] { "POST /api/trials/request", "POST /api/trials/confirm" })
        {
            var endpoint = Assert.Single(endpoints, endpoint => DescribeEndpoint(endpoint) == trialRoute);
            var rateLimit = endpoint.Metadata.GetMetadata<Microsoft.AspNetCore.RateLimiting.EnableRateLimitingAttribute>();
            Assert.NotNull(rateLimit);
            Assert.Equal("checkout", rateLimit.PolicyName);
        }

        var policies = endpoints.SelectMany(endpoint => endpoint.Metadata.GetOrderedMetadata<IAuthorizeData>())
            .Select(data => data.Policy)
            .Where(policy => !string.IsNullOrWhiteSpace(policy))
            .Select(policy => policy!)
            .ToHashSet(StringComparer.Ordinal);
        var expectedPolicies = new HashSet<string>(StringComparer.Ordinal)
        {
            "asset.read", "asset.write", "settings.manage", "people.read", "people.manage",
            "people.files.read", "people.files.manage", "company.member", "platform.admin"
        };
        Assert.True(expectedPolicies.SetEquals(policies),
            "Review API authorization policy coverage. Unexpected: " +
            string.Join(", ", policies.Except(expectedPolicies).OrderBy(x => x, StringComparer.Ordinal)) +
            "; unused: " +
            string.Join(", ", expectedPolicies.Except(policies).OrderBy(x => x, StringComparer.Ordinal)));
    }

    [Fact]
    public async Task Directory_name_merge_requires_approval_and_preserves_company_scope()
    {
        using var csrfResponse = await SendAsAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var suffix = Guid.NewGuid().ToString("N");
        var oldLocation = $"Old location {suffix}"; var targetLocation = $"Target location {suffix}";
        var oldDepartment = $"Old department {suffix}"; var targetDepartment = $"Target department {suffix}";
        Guid categoryId, ownOldAssetId = Guid.NewGuid(), ownTargetAssetId = Guid.NewGuid(), foreignAssetId = Guid.NewGuid();
        var oldEmployeeId = Guid.NewGuid(); var targetEmployeeId = Guid.NewGuid(); var foreignEmployeeId = Guid.NewGuid();
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            categoryId = await db.Assets.Where(x => x.CompanyId == _companyId).Select(x => x.CategoryId).FirstAsync();
            db.Assets.AddRange(
                new Asset { Id = ownOldAssetId, CompanyId = _companyId, AssetTag = $"OLD-{suffix}", Name = "Old location asset", CategoryId = categoryId, Location = oldLocation },
                new Asset { Id = ownTargetAssetId, CompanyId = _companyId, AssetTag = $"TARGET-{suffix}", Name = "Target location asset", CategoryId = categoryId, Location = targetLocation },
                new Asset { Id = foreignAssetId, CompanyId = _otherCompanyId, AssetTag = $"FOREIGN-{suffix}", Name = "Foreign location asset", CategoryId = await db.Assets.Where(x => x.CompanyId == _otherCompanyId).Select(x => x.CategoryId).FirstAsync(), Location = oldLocation });
            db.Employees.AddRange(
                new Employee { Id = oldEmployeeId, CompanyId = _companyId, EmployeeNumber = $"OLD-{suffix}", DisplayName = "Old department employee", Department = oldDepartment },
                new Employee { Id = targetEmployeeId, CompanyId = _companyId, EmployeeNumber = $"TARGET-{suffix}", DisplayName = "Target department employee", Department = targetDepartment },
                new Employee { Id = foreignEmployeeId, CompanyId = _otherCompanyId, EmployeeNumber = $"FOREIGN-{suffix}", DisplayName = "Foreign department employee", Department = oldDepartment });
            await db.SaveChangesAsync();
        }

        using (var unapprovedLocation = await SendAsRoleAsync(HttpMethod.Patch, "/api/locations/rename", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { currentName = oldLocation, newName = targetLocation, merge = false }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, unapprovedLocation.StatusCode);
        using (var locationMerge = await SendAsRoleAsync(HttpMethod.Patch, "/api/locations/rename", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { currentName = oldLocation, newName = targetLocation, merge = true }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, locationMerge.StatusCode);
            using var payload = JsonDocument.Parse(await locationMerge.Content.ReadAsStringAsync());
            Assert.Equal(1, payload.RootElement.GetProperty("updatedCount").GetInt32());
        }
        using (var unapprovedDepartment = await SendAsRoleAsync(HttpMethod.Patch, "/api/departments/rename", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { currentName = oldDepartment, newName = targetDepartment, merge = false }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, unapprovedDepartment.StatusCode);
        using (var departmentMerge = await SendAsRoleAsync(HttpMethod.Patch, "/api/departments/rename", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { currentName = oldDepartment, newName = targetDepartment, merge = true }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, departmentMerge.StatusCode);
            using var payload = JsonDocument.Parse(await departmentMerge.Content.ReadAsStringAsync());
            Assert.Equal(1, payload.RootElement.GetProperty("employeeCount").GetInt32());
        }

        await using var verifyScope = _factory!.Services.CreateAsyncScope();
        var verifyDb = verifyScope.ServiceProvider.GetRequiredService<AppDbContext>();
        Assert.Equal(targetLocation, await verifyDb.Assets.Where(x => x.CompanyId == _companyId && x.Id == ownOldAssetId).Select(x => x.Location).SingleAsync());
        Assert.Equal(oldLocation, await verifyDb.Assets.Where(x => x.CompanyId == _otherCompanyId && x.Id == foreignAssetId).Select(x => x.Location).SingleAsync());
        Assert.Equal(targetDepartment, await verifyDb.Employees.Where(x => x.CompanyId == _companyId && x.Id == oldEmployeeId).Select(x => x.Department).SingleAsync());
        Assert.Equal(oldDepartment, await verifyDb.Employees.Where(x => x.CompanyId == _otherCompanyId && x.Id == foreignEmployeeId).Select(x => x.Department).SingleAsync());
        Assert.Equal(2, await verifyDb.AuditEntries.CountAsync(x => x.CompanyId == _companyId && x.Action == "Renamed" &&
            (x.TargetType == "Location" || x.TargetType == "Department") && x.Details!.Contains(suffix)));
    }

    [Fact]
    public async Task Company_units_are_hierarchical_tenant_scoped_and_archived_without_hard_deletes()
    {
        using var csrfResponse = await SendAsAdminAsync("/api/session/csrf");
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var suffix = _userId.ToString("N");
        var rootName = $"Org root {suffix}";
        var childName = $"Org child {suffix}";
        var otherUnitId = Guid.NewGuid();
        var auditorId = Guid.NewGuid();
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.CompanyUnits.Add(new CompanyUnit { Id = otherUnitId, CompanyId = _otherCompanyId,
                Name = $"Private company unit {suffix}", NormalizedName = $"PRIVATE COMPANY UNIT {suffix}" });
            db.CompanyMemberships.Add(new CompanyMembership { CompanyId = _otherCompanyId,
                UserId = _sameCompanyOtherUserId, RoleKey = "admin" });
            db.Users.Add(new EnvanterUser { Id = auditorId, UserName = $"company-units-auditor-{auditorId:N}",
                NormalizedUserName = $"COMPANY-UNITS-AUDITOR-{auditorId:N}".ToUpperInvariant(),
                Email = $"company-units-auditor-{auditorId:N}@example.invalid",
                NormalizedEmail = $"COMPANY-UNITS-AUDITOR-{auditorId:N}@EXAMPLE.INVALID".ToUpperInvariant(),
                EmailConfirmed = true, SecurityStamp = Guid.NewGuid().ToString("N"),
                ConcurrencyStamp = Guid.NewGuid().ToString("N"), DisplayName = "Company unit auditor" });
            db.CompanyMemberships.Add(new CompanyMembership { CompanyId = _companyId,
                UserId = auditorId, RoleKey = "auditor" });
            await db.SaveChangesAsync();
        }

        using (var readOnlyRole = await SendAsUserAsync(HttpMethod.Get, "/api/company-units", auditorId, _companyId, role: "auditor"))
            Assert.Equal(HttpStatusCode.OK, readOnlyRole.StatusCode);
        using (var readOnlyWrite = await SendAsUserAsync(HttpMethod.Post, "/api/company-units", auditorId, _companyId,
                   System.Net.Http.Json.JsonContent.Create(new { name = $"Denied {suffix}" }), requestToken, antiforgeryCookie, role: "auditor"))
            Assert.Equal(HttpStatusCode.Forbidden, readOnlyWrite.StatusCode);

        Guid rootId;
        using (var createRoot = await SendAsRoleAsync(HttpMethod.Post, "/api/company-units", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { name = rootName, code = $"ROOT-{suffix}", unitType = CompanyUnitTypes.LegalEntity }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, createRoot.StatusCode);
            using var payload = JsonDocument.Parse(await createRoot.Content.ReadAsStringAsync());
            rootId = payload.RootElement.GetProperty("id").GetGuid();
            Assert.Equal(CompanyUnitTypes.LegalEntity, payload.RootElement.GetProperty("unitType").GetString());
        }
        Guid childId;
        using (var createChild = await SendAsRoleAsync(HttpMethod.Post, "/api/company-units", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { name = childName, parentCompanyUnitId = rootId, unitType = CompanyUnitTypes.Branch }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, createChild.StatusCode);
            using var payload = JsonDocument.Parse(await createChild.Content.ReadAsStringAsync());
            childId = payload.RootElement.GetProperty("id").GetGuid();
            Assert.Equal(CompanyUnitTypes.Branch, payload.RootElement.GetProperty("unitType").GetString());
        }
        Guid linkedLocationId;
        var linkedLocationName = $"Unit-linked location {suffix}";
        using (var createLinkedLocation = await SendAsRoleAsync(HttpMethod.Post, "/api/locations/catalog", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { name = linkedLocationName, companyUnitId = rootId }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, createLinkedLocation.StatusCode);
            using var payload = JsonDocument.Parse(await createLinkedLocation.Content.ReadAsStringAsync());
            linkedLocationId = payload.RootElement.GetProperty("id").GetGuid();
            Assert.Equal(rootId, payload.RootElement.GetProperty("companyUnitId").GetGuid());
        }
        using (var deniedUnitBinding = await SendAsUserAsync(HttpMethod.Post, "/api/locations/catalog", auditorId, _companyId,
                   System.Net.Http.Json.JsonContent.Create(new { name = $"Denied unit binding {suffix}", companyUnitId = rootId }), requestToken, antiforgeryCookie, role: "auditor"))
            Assert.Equal(HttpStatusCode.Forbidden, deniedUnitBinding.StatusCode);
        using (var foreignUnitBinding = await SendAsRoleAsync(HttpMethod.Post, "/api/locations/catalog", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { name = $"Foreign unit binding {suffix}", companyUnitId = otherUnitId }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, foreignUnitBinding.StatusCode);
        using (var locationDirectory = await SendAsRoleAsync(HttpMethod.Get, "/api/locations", "admin"))
        {
            Assert.Equal(HttpStatusCode.OK, locationDirectory.StatusCode);
            using var payload = JsonDocument.Parse(await locationDirectory.Content.ReadAsStringAsync());
            var location = Assert.Single(payload.RootElement.GetProperty("items").EnumerateArray(), item =>
