                    PlanId = plan.Id, TermDays = 30, SubtotalAmount = 1500, Amount = 1500, Currency = "TRY", Status = "PaymentFailed",
                    CheckoutTokenHash = "second-secret", CheckoutPageUrlProtected = "second-protected-url",
