                Email = $"{marker}@example.invalid", NormalizedEmail = $"{marker}@EXAMPLE.INVALID",
                EmailConfirmed = true, PhoneNumber = "+905551234567", PhoneNumberConfirmed = true,
                TwoFactorEnabled = true, LockoutEnabled = true, AccessFailedCount = 2,
