        Assert.InRange((profileJson.RootElement.GetProperty("account").GetProperty("accountCreatedAt").GetDateTimeOffset() - accountCreatedAt).Duration(),
            TimeSpan.Zero, TimeSpan.FromMilliseconds(1));
