                   System.Net.Http.Json.JsonContent.Create(new { roleKey = "admin", note = "acceptance" })))
            Assert.Equal(HttpStatusCode.Forbidden, tenantRoleChange.StatusCode);
        using (var noCsrf = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, membershipPath + "/role",
                   System.Net.Http.Json.JsonContent.Create(new { roleKey = "admin", note = "acceptance" })))
            Assert.Equal(HttpStatusCode.BadRequest, noCsrf.StatusCode);
        using (var protectedOwnerRole = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch,
                   $"/api/platform/members/{userId}/memberships/{_companyId}/role",
                   System.Net.Http.Json.JsonContent.Create(new { roleKey = "admin", note = "acceptance" }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, protectedOwnerRole.StatusCode);
        using (var protectedOwnerRemoval = await SendAsPlatformAdminRequestAsync(HttpMethod.Delete,
                   $"/api/platform/members/{userId}/memberships/{_companyId}",
                   System.Net.Http.Json.JsonContent.Create(new { note = "acceptance" }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, protectedOwnerRemoval.StatusCode);
        var ownerTransferPath = $"/api/platform/members/{userId}/memberships/{_companyId}/owner-transfer";
        using (var tenantTransfer = await SendAsUserAsync(HttpMethod.Post, ownerTransferPath, userId, _companyId,
                   System.Net.Http.Json.JsonContent.Create(new
                   {
                       newOwnerEmail = $"new-owner-{newOwnerId:N}@example.invalid", formerOwnerRoleKey = "admin",
                       note = "Unauthorized owner transfer", confirmTransfer = true
                   })))
            Assert.Equal(HttpStatusCode.Forbidden, tenantTransfer.StatusCode);
        using (var transferWithoutCsrf = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, ownerTransferPath,
                   System.Net.Http.Json.JsonContent.Create(new
                   {
                       newOwnerEmail = $"new-owner-{newOwnerId:N}@example.invalid", formerOwnerRoleKey = "admin",
                       note = "Owner transfer", confirmTransfer = true
                   })))
            Assert.Equal(HttpStatusCode.BadRequest, transferWithoutCsrf.StatusCode);
        using (var transferToNonMember = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, ownerTransferPath,
                   System.Net.Http.Json.JsonContent.Create(new
                   {
                       newOwnerEmail = $"legacy-{legacyUserId:N}@example.invalid", formerOwnerRoleKey = "admin",
                       note = "Owner transfer", confirmTransfer = true
                   }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, transferToNonMember.StatusCode);
        using (var unconfirmedTransfer = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, ownerTransferPath,
                   System.Net.Http.Json.JsonContent.Create(new
                   {
                       newOwnerEmail = $"new-owner-{newOwnerId:N}@example.invalid", formerOwnerRoleKey = "admin",
                       note = "Owner transfer", confirmTransfer = false
                   }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, unconfirmedTransfer.StatusCode);
        using (var ownershipTransfer = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, ownerTransferPath,
                   System.Net.Http.Json.JsonContent.Create(new
                   {
                       newOwnerEmail = $"new-owner-{newOwnerId:N}@example.invalid", formerOwnerRoleKey = "admin",
                       note = "Company owner requested an audited transfer", confirmTransfer = true
                   }), requestToken, antiforgeryCookie))
        {
            var transferBody = await ownershipTransfer.Content.ReadAsStringAsync();
            Assert.True(ownershipTransfer.StatusCode == HttpStatusCode.OK, $"{ownershipTransfer.StatusCode}: {transferBody}");
            using var transferPayload = JsonDocument.Parse(transferBody);
            Assert.True(transferPayload.RootElement.GetProperty("transferred").GetBoolean());
            Assert.Equal("admin", transferPayload.RootElement.GetProperty("formerOwnerRole").GetString());
            Assert.Equal("owner", transferPayload.RootElement.GetProperty("newOwnerRole").GetString());
            Assert.Equal(1, transferPayload.RootElement.GetProperty("revokedFormerOwnerSessions").GetInt32());
        }
        using (var changedRole = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, membershipPath + "/role",
                   System.Net.Http.Json.JsonContent.Create(new { roleKey = "admin", note = "Role reviewed by acceptance" }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, changedRole.StatusCode);
            using var rolePayload = JsonDocument.Parse(await changedRole.Content.ReadAsStringAsync());
            Assert.True(rolePayload.RootElement.GetProperty("changed").GetBoolean());
            Assert.Equal("admin", rolePayload.RootElement.GetProperty("roleKey").GetString());
        }
        using (var sameRole = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, membershipPath + "/role",
                   System.Net.Http.Json.JsonContent.Create(new { roleKey = "admin", note = "Repeated safe action" }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, sameRole.StatusCode);
            using var sameRolePayload = JsonDocument.Parse(await sameRole.Content.ReadAsStringAsync());
            Assert.False(sameRolePayload.RootElement.GetProperty("changed").GetBoolean());
        }
        using (var removedMembership = await SendAsPlatformAdminRequestAsync(HttpMethod.Delete, membershipPath,
                   System.Net.Http.Json.JsonContent.Create(new { note = "Membership no longer needed" }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, removedMembership.StatusCode);
            using var removalPayload = JsonDocument.Parse(await removedMembership.Content.ReadAsStringAsync());
            Assert.Equal(1, removalPayload.RootElement.GetProperty("revokedSessions").GetInt32());
        }
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            Assert.False(await db.CompanyMemberships.AnyAsync(x => x.UserId == userId && x.CompanyId == _otherCompanyId));
            Assert.Equal("admin", await db.CompanyMemberships.Where(x => x.UserId == userId && x.CompanyId == _companyId)
                .Select(x => x.RoleKey).SingleAsync());
            Assert.Equal("owner", await db.CompanyMemberships.Where(x => x.UserId == newOwnerId && x.CompanyId == _companyId)
                .Select(x => x.RoleKey).SingleAsync());
            Assert.Equal(1, await db.CompanyMemberships.CountAsync(x => x.CompanyId == _companyId && x.RoleKey == "owner"));
            Assert.NotNull(await db.UserSessions.Where(x => x.UserId == userId && x.CompanyId == _companyId)
                .Select(x => x.RevokedAt).SingleAsync());
            Assert.NotNull(await db.UserSessions.Where(x => x.UserId == userId && x.CompanyId == _otherCompanyId)
                .Select(x => x.RevokedAt).SingleAsync());
            var roleAudit = await db.PlatformAuditEntries.SingleAsync(x => x.TargetType == "CompanyMembership" &&
                x.TargetId == userId && x.CompanyId == _otherCompanyId && x.Action == "MemberRoleChanged");
            Assert.Contains("Role reviewed by acceptance", roleAudit.Details, StringComparison.Ordinal);
            Assert.True(await db.PlatformAuditEntries.AnyAsync(x => x.TargetType == "CompanyMembership" &&
                x.TargetId == userId && x.CompanyId == _otherCompanyId && x.Action == "MemberRemoved"));
            var ownerTransferAudit = await db.PlatformAuditEntries.SingleAsync(x => x.TargetType == "Company" &&
                x.TargetId == _companyId && x.CompanyId == _companyId && x.Action == "MemberOwnerTransferred");
            Assert.Contains("Company owner requested an audited transfer", ownerTransferAudit.Details, StringComparison.Ordinal);
            Assert.True(await db.AuditEntries.AnyAsync(x => x.TargetType == "CompanyMembership" &&
                x.TargetId == userId && x.CompanyId == _companyId && x.Action == "OwnerTransferredOut"));
            Assert.True(await db.AuditEntries.AnyAsync(x => x.TargetType == "CompanyMembership" &&
                x.TargetId == newOwnerId && x.CompanyId == _companyId && x.Action == "OwnerTransferredIn"));
        }
        var timeline = new List<string>();
        var timelineBody = new List<string>();
        var timelinePages = 0;
        for (var page = 1; page <= 4; page++)
        {
            using var timelineResponse = await SendAsPlatformAdminAsync($"/api/platform/members/{userId}/timeline?page={page}&pageSize=4");
            Assert.Equal(HttpStatusCode.OK, timelineResponse.StatusCode);
            var pageBody = await timelineResponse.Content.ReadAsStringAsync();
            timelineBody.Add(pageBody);
            timelinePages++;
            using var timelinePayload = JsonDocument.Parse(pageBody);
            var timelineRoot = timelinePayload.RootElement;
            timeline.AddRange(timelineRoot.GetProperty("items").EnumerateArray()
                .Select(item => item.GetProperty("title").GetString()!));
            if (!timelineRoot.GetProperty("hasMore").GetBoolean()) break;
        }
        Assert.Contains("Demo talebi alındı", timeline);
        Assert.Contains("Hesap oluşturuldu", timeline);
        Assert.Contains("Ödeme doğrulandı", timeline);
        Assert.Contains("Satın alma kaydı oluşturuldu", timeline);
        Assert.Contains("Demo erişimi tanımlandı", timeline);
        Assert.Contains("Şirket üyeliği kaldırıldı", timeline);
        Assert.Contains("Şirket sahipliği devredildi", timeline);
        Assert.True(timelinePages > 1, "The member timeline should paginate when more than four events exist.");
        var serializedTimeline = string.Join('\n', timelineBody);
        Assert.Contains($"pending-member-checkout-{_companyId:N}", serializedTimeline, StringComparison.Ordinal);
        Assert.Contains("Unprovisioned Acceptance Company", serializedTimeline, StringComparison.Ordinal);
        Assert.Contains("1200", serializedTimeline, StringComparison.Ordinal);
        Assert.DoesNotContain("pending-member-token-hash-must-not-leak", serializedTimeline, StringComparison.Ordinal);
        Assert.DoesNotContain("pending-member-protected-url-must-not-leak", serializedTimeline, StringComparison.Ordinal);
        Assert.DoesNotContain("checkout-token-hash-must-not-leak", serializedTimeline, StringComparison.Ordinal);
        Assert.DoesNotContain("protected-checkout-url-must-not-leak", serializedTimeline, StringComparison.Ordinal);
    }

    [Fact]
    public async Task Platform_admin_can_invite_new_and_existing_members_with_company_scope_and_retryable_email()
    {
        var plan = new SubscriptionPlan
        {
            Code = $"member-invite-{_companyId:N}"[..40], Name = "Platform member invite acceptance",
            DeploymentKind = "cloud", IsActive = true, IsPublic = true
        };
        var email = $"platform-invite-{Guid.NewGuid():N}@example.invalid";
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.SubscriptionPlans.Add(plan);
            db.TenantSubscriptions.AddRange(
                new TenantSubscription { CompanyId = _companyId, PlanId = plan.Id, Status = "Active", EndsAt = DateTimeOffset.UtcNow.AddDays(60) },
                new TenantSubscription { CompanyId = _otherCompanyId, PlanId = plan.Id, Status = "Active", EndsAt = DateTimeOffset.UtcNow.AddDays(60) });
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            await db.SaveChangesAsync();
        }

        using var csrfResponse = await SendAsPlatformAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var invite = new { companyId = _companyId, fullName = "New Platform Invite", email, roleKey = "viewer" };

        using (var denied = await SendAsUserAsync(HttpMethod.Post, "/api/platform/members/invite", _userId, _companyId,
                   System.Net.Http.Json.JsonContent.Create(invite)))
            Assert.Equal(HttpStatusCode.Forbidden, denied.StatusCode);

        using (var invalidRole = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, "/api/platform/members/invite",
                   System.Net.Http.Json.JsonContent.Create(new { companyId = _companyId, fullName = "Invalid Role", email, roleKey = "owner" }),
                   requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, invalidRole.StatusCode);

        Guid invitedUserId;
        using (var created = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, "/api/platform/members/invite",
                   System.Net.Http.Json.JsonContent.Create(invite), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, created.StatusCode);
            using var payload = JsonDocument.Parse(await created.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("invitationSent").GetBoolean());
            Assert.False(payload.RootElement.GetProperty("resent").GetBoolean());
            invitedUserId = payload.RootElement.GetProperty("userId").GetGuid();
        }

        using (var resent = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, "/api/platform/members/invite",
                   System.Net.Http.Json.JsonContent.Create(invite), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, resent.StatusCode);
            using var payload = JsonDocument.Parse(await resent.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("invitationSent").GetBoolean());
            Assert.True(payload.RootElement.GetProperty("resent").GetBoolean());
            Assert.Equal(invitedUserId, payload.RootElement.GetProperty("userId").GetGuid());
        }

        using (var existingAccount = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, "/api/platform/members/invite",
                   System.Net.Http.Json.JsonContent.Create(new
                   {
                       companyId = _otherCompanyId, fullName = "Security Acceptance User",
                       email = $"acceptance-{_userId:N}@example.invalid", roleKey = "asset_manager"
                   }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, existingAccount.StatusCode);
            using var payload = JsonDocument.Parse(await existingAccount.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("invitationSent").GetBoolean());
            Assert.Equal(_userId, payload.RootElement.GetProperty("userId").GetGuid());
        }

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var invited = await db.Users.SingleAsync(account => account.Id == invitedUserId);
            Assert.Equal(email, invited.Email);
            Assert.False(invited.EmailConfirmed);
            Assert.Equal(1, await db.CompanyMemberships.CountAsync(membership => membership.CompanyId == _companyId && membership.UserId == invitedUserId));
            Assert.Equal("viewer", await db.CompanyMemberships.Where(membership => membership.CompanyId == _companyId && membership.UserId == invitedUserId)
                .Select(membership => membership.RoleKey).SingleAsync());
            Assert.Equal("admin", await db.CompanyMemberships.Where(membership => membership.CompanyId == _companyId && membership.UserId == _userId)
                .Select(membership => membership.RoleKey).SingleAsync());
            Assert.Equal("asset_manager", await db.CompanyMemberships.Where(membership => membership.CompanyId == _otherCompanyId && membership.UserId == _userId)
                .Select(membership => membership.RoleKey).SingleAsync());
            Assert.Contains(await db.PlatformAuditEntries.AsNoTracking().Where(entry => entry.CompanyId == _otherCompanyId).Select(entry => entry.Action).ToListAsync(),
                action => action == "MemberInvited");
        }

        Assert.Equal(3, _smtpCapture.Messages.Count);
        Assert.Contains(_smtpCapture.Messages, message => message.Contains($"To: {email}", StringComparison.OrdinalIgnoreCase));
        Assert.All(_smtpCapture.Messages.Where(message => message.Contains($"To: {email}", StringComparison.OrdinalIgnoreCase)),
            message => Assert.Contains($"https://acceptance-{_companyId:N}.envantertr.com/", DecodeMimeBody(message), StringComparison.Ordinal));
        var existingAccountMessage = Assert.Single(_smtpCapture.Messages, message =>
            message.Contains($"To: acceptance-{_userId:N}@example.invalid", StringComparison.OrdinalIgnoreCase));
        Assert.Contains("Other security acceptance company", DecodeMimeBody(existingAccountMessage), StringComparison.Ordinal);
        Assert.Contains($"https://other-{_otherCompanyId:N}.envantertr.com/", DecodeMimeBody(existingAccountMessage), StringComparison.Ordinal);
        Assert.DoesNotContain("token=", existingAccountMessage, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task Public_demo_requests_are_validated_deduplicated_and_visible_only_to_platform_admins()
    {
        var email = $"demo-request-{Guid.NewGuid():N}@example.invalid";
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            await db.SaveChangesAsync();
        }

        using var client = _factory.CreateClient();
        var missingConsent = new
        {
            companyName = "Demo Request Acceptance", contactName = "Synthetic Contact", email,
            phone = "+90 212 555 0000", jobTitle = "IT Manager", teamSize = "51-200",
            assetCount = "251-1000", message = "Synthetic demo request", consent = false, website = ""
        };
        using (var rejected = await client.PostAsJsonAsync("/api/demo-requests", missingConsent))
            Assert.Equal(HttpStatusCode.BadRequest, rejected.StatusCode);

        var request = new
        {
            companyName = "Demo Request Acceptance", contactName = "Synthetic Contact", email = email.ToUpperInvariant(),
            phone = "+90 212 555 0000", jobTitle = "IT Manager", teamSize = "51-200",
            assetCount = "251-1000", message = "Synthetic demo request", consent = true, website = ""
        };
        using (var accepted = await client.PostAsJsonAsync("/api/demo-requests", request))
            Assert.Equal(HttpStatusCode.Accepted, accepted.StatusCode);
        using (var duplicate = await client.PostAsJsonAsync("/api/demo-requests", request))
            Assert.Equal(HttpStatusCode.Accepted, duplicate.StatusCode);

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var lead = await db.PlatformDemoRequests.SingleAsync(x => x.Email == email);
            Assert.Equal("Demo Request Acceptance", lead.CompanyName);
            Assert.Equal("Synthetic Contact", lead.ContactName);
            Assert.Equal("New", lead.Status);
            Assert.Equal("PublicWebsite", lead.Source);
            Assert.Equal("demo-request-v1", lead.ConsentNoticeVersion);
            Assert.Equal("Synthetic demo request", lead.Message);
        }

        using (var anonymous = await client.GetAsync("/api/platform/demo-requests"))
            Assert.Equal(HttpStatusCode.Unauthorized, anonymous.StatusCode);
        using (var tenant = await SendAsUserAsync(HttpMethod.Get, "/api/platform/demo-requests", _userId, _companyId))
            Assert.Equal(HttpStatusCode.Forbidden, tenant.StatusCode);
        using (var platform = await SendAsPlatformAdminAsync($"/api/platform/demo-requests?q={Uri.EscapeDataString(email)}"))
        {
            Assert.Equal(HttpStatusCode.OK, platform.StatusCode);
            using var payload = JsonDocument.Parse(await platform.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("total").GetInt32() >= 1);
            Assert.Equal(email, payload.RootElement.GetProperty("items")[0].GetProperty("email").GetString());
        }

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var lead = await db.PlatformDemoRequests.SingleAsync(x => x.Email == email);
            lead.FollowUpAt = DateTimeOffset.UtcNow.AddMinutes(-1);
            await db.SaveChangesAsync();
        }
        using (var overdue = await SendAsPlatformAdminAsync($"/api/platform/demo-requests?followUp=overdue&q={Uri.EscapeDataString(email)}"))
        {
            Assert.Equal(HttpStatusCode.OK, overdue.StatusCode);
            using var payload = JsonDocument.Parse(await overdue.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("total").GetInt32() >= 1);
            Assert.Equal(email, payload.RootElement.GetProperty("items")[0].GetProperty("email").GetString());
        }
        using (var invalidFollowUp = await SendAsPlatformAdminAsync("/api/platform/demo-requests?followUp=tomorrow"))
            Assert.Equal(HttpStatusCode.BadRequest, invalidFollowUp.StatusCode);
    }

    [Fact]
    public async Task Platform_demo_request_stages_require_real_demo_or_paid_company_subscription_and_are_audited()
    {
        var email = $"demo-stage-{Guid.NewGuid():N}@example.invalid";
        var leadId = Guid.NewGuid();
        var plan = new SubscriptionPlan
        {
            Code = $"demo-stage-{_companyId:N}"[..40], Name = "Demo lifecycle acceptance", DeploymentKind = "cloud", IsActive = true
        };
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            db.SubscriptionPlans.Add(plan);
            db.PlatformDemoRequests.Add(new PlatformDemoRequest
            {
                Id = leadId, CompanyName = "Lifecycle Company", ContactName = "Synthetic Contact", Email = email,
                Source = "PublicWebsite", Status = "New", ConsentNoticeVersion = "demo-request-v1"
            });
            await db.SaveChangesAsync();
        }

        using var csrfResponse = await SendAsPlatformAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var demoStage = new { status = "DemoGranted", assignedAdminUserId = (Guid?)_userId, followUpAt = (DateTimeOffset?)null, companyId = (Guid?)_companyId, note = "Synthetic demo granted" };

        using (var falseDemo = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, $"/api/platform/demo-requests/{leadId}",
                   JsonContent.Create(demoStage), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, falseDemo.StatusCode);

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.TenantSubscriptions.Add(new TenantSubscription
            {
                CompanyId = _companyId, PlanId = plan.Id, Status = "Trial", IsDemo = true,
                StartsAt = DateTimeOffset.UtcNow.AddDays(-15), EndsAt = DateTimeOffset.UtcNow.AddDays(-1)
            });
            await db.SaveChangesAsync();
        }
        using (var expiredDemo = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, $"/api/platform/demo-requests/{leadId}",
                   JsonContent.Create(demoStage), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, expiredDemo.StatusCode);
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var subscription = await db.TenantSubscriptions.SingleAsync(x => x.CompanyId == _companyId);
            subscription.StartsAt = DateTimeOffset.UtcNow.AddMinutes(-1);
            subscription.EndsAt = DateTimeOffset.UtcNow.AddDays(14);
            await db.SaveChangesAsync();
        }
        using (var granted = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, $"/api/platform/demo-requests/{leadId}",
                   JsonContent.Create(demoStage), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, granted.StatusCode);
            using var payload = JsonDocument.Parse(await granted.Content.ReadAsStringAsync());
            Assert.Equal("DemoGranted", payload.RootElement.GetProperty("status").GetString());
            Assert.False(string.IsNullOrWhiteSpace(payload.RootElement.GetProperty("demoGrantedAt").GetString()));
        }

        var convertedStage = new { status = "Converted", assignedAdminUserId = (Guid?)_userId, followUpAt = (DateTimeOffset?)null, companyId = (Guid?)_companyId, note = "Synthetic conversion" };
        using (var prematureConversion = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, $"/api/platform/demo-requests/{leadId}",
                   JsonContent.Create(convertedStage), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, prematureConversion.StatusCode);

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var subscription = await db.TenantSubscriptions.SingleAsync(x => x.CompanyId == _companyId);
            subscription.IsDemo = false;
            await db.SaveChangesAsync();
        }
        using (var unpaidTrial = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, $"/api/platform/demo-requests/{leadId}",
                   JsonContent.Create(convertedStage), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, unpaidTrial.StatusCode);
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var subscription = await db.TenantSubscriptions.SingleAsync(x => x.CompanyId == _companyId);
            subscription.Status = "Active";
            await db.SaveChangesAsync();
        }
        using (var converted = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch, $"/api/platform/demo-requests/{leadId}",
                   JsonContent.Create(convertedStage), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, converted.StatusCode);
            using var payload = JsonDocument.Parse(await converted.Content.ReadAsStringAsync());
            Assert.Equal("Converted", payload.RootElement.GetProperty("status").GetString());
        }
        using (var detail = await SendAsPlatformAdminAsync($"/api/platform/demo-requests/{leadId}"))
        {
            Assert.Equal(HttpStatusCode.OK, detail.StatusCode);
            using var payload = JsonDocument.Parse(await detail.Content.ReadAsStringAsync());
            Assert.Equal("Lifecycle Company", payload.RootElement.GetProperty("lead").GetProperty("companyName").GetString());
            Assert.True(payload.RootElement.GetProperty("history").GetArrayLength() >= 2);
            Assert.Contains("Synthetic conversion", await detail.Content.ReadAsStringAsync(), StringComparison.Ordinal);
        }
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var actions = await db.PlatformAuditEntries.AsNoTracking().Where(x => x.TargetType == "PlatformDemoRequest" && x.TargetId == leadId)
                .Select(x => x.Action).ToListAsync();
            Assert.Contains("DemoRequestStatusChanged", actions);
        }
    }

    [Fact]
    public async Task Platform_customer_lifecycle_is_validated_assigned_audited_and_persisted()
    {
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            await db.SaveChangesAsync();
        }

        using (var denied = await SendAsUserAsync(HttpMethod.Patch, $"/api/platform/companies/{_companyId}/lifecycle",
            _userId, _companyId, JsonContent.Create(new { stage = "Onboarding", assignedAdminUserId = _userId })))
            Assert.Equal(HttpStatusCode.Forbidden, denied.StatusCode);

        using var csrfResponse = await SendAsAdminAsync("/api/session/csrf");
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));

        using (var invalid = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch,
            $"/api/platform/companies/{_companyId}/lifecycle",
            JsonContent.Create(new { stage = "MadeUp", assignedAdminUserId = _userId }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, invalid.StatusCode);

        var followUpAt = DateTimeOffset.UtcNow.AddDays(3);
        using (var update = await SendAsPlatformAdminRequestAsync(HttpMethod.Patch,
            $"/api/platform/companies/{_companyId}/lifecycle",
            JsonContent.Create(new { stage = "Onboarding", assignedAdminUserId = _userId,
                nextFollowUpAt = followUpAt, note = "Kickoff completed; data import scheduled." }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.OK, update.StatusCode);

        using (var detail = await SendAsPlatformAdminAsync($"/api/platform/companies/{_companyId}"))
        {
            Assert.Equal(HttpStatusCode.OK, detail.StatusCode);
            using var payload = JsonDocument.Parse(await detail.Content.ReadAsStringAsync());
            var company = payload.RootElement.GetProperty("company");
            Assert.Equal("Onboarding", company.GetProperty("lifecycleStage").GetString());
            Assert.Equal(_userId.ToString(), company.GetProperty("lifecycleOwnerId").GetString());
            Assert.Equal(1, payload.RootElement.GetProperty("lifecycleHistory").GetArrayLength());
            Assert.Contains("Kickoff completed", payload.RootElement.GetProperty("lifecycleHistory")[0].GetProperty("details").GetString());
        }

        await using var verifyScope = _factory!.Services.CreateAsyncScope();
        var verifyDb = verifyScope.ServiceProvider.GetRequiredService<AppDbContext>();
        var saved = await verifyDb.Companies.SingleAsync(x => x.Id == _companyId);
        Assert.Equal("Onboarding", saved.CustomerLifecycleStage);
        Assert.Equal(_userId, saved.PlatformOwnerUserId);
        Assert.True(saved.PlatformNextFollowUpAt > DateTimeOffset.UtcNow.AddDays(2));
        Assert.True(await verifyDb.PlatformAuditEntries.AnyAsync(x => x.CompanyId == _companyId &&
            x.Action == "CustomerLifecycleUpdated" && x.Details!.Contains("Kickoff completed")));

        using (var invalidFilter = await SendAsPlatformAdminAsync("/api/platform/companies?followUp=tomorrow"))
            Assert.Equal(HttpStatusCode.BadRequest, invalidFilter.StatusCode);
        saved.PlatformNextFollowUpAt = DateTimeOffset.UtcNow.AddHours(-2);
        await verifyDb.SaveChangesAsync();
        using (var overdue = await SendAsPlatformAdminAsync("/api/platform/companies?followUp=overdue&page=1&pageSize=10"))
        {
            Assert.Equal(HttpStatusCode.OK, overdue.StatusCode);
            using var payload = JsonDocument.Parse(await overdue.Content.ReadAsStringAsync());
            Assert.Contains(payload.RootElement.GetProperty("items").EnumerateArray(), item =>
                item.GetProperty("id").GetGuid() == _companyId &&
                item.GetProperty("nextFollowUpAt").GetDateTimeOffset() <= DateTimeOffset.UtcNow);
        }
    }

    [Fact]
    public async Task Platform_company_csv_export_is_authorized_filtered_complete_and_spreadsheet_safe()
    {
        var marker = $"=2+2;CSV-{Guid.NewGuid():N}";
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            var ownCompany = await db.Companies.SingleAsync(x => x.Id == _companyId);
            ownCompany.Name = marker;
            ownCompany.Slug = $"csv-{Guid.NewGuid():N}";
            ownCompany.ContactEmail = "csv-owner@example.invalid";
            ownCompany.IsActive = true;
            ownCompany.CreatedAt = new DateTimeOffset(2026, 10, 10, 12, 0, 0, TimeSpan.Zero);
            var logoFileName = $"{Guid.NewGuid():N}.png";
            ownCompany.BrandLogoPath = logoFileName;
            var otherCompany = await db.Companies.SingleAsync(x => x.Id == _otherCompanyId);
            otherCompany.Name = $"Excluded {marker}";
            otherCompany.IsActive = false;
            otherCompany.CreatedAt = new DateTimeOffset(2026, 10, 11, 12, 0, 0, TimeSpan.Zero);
            var plan = new SubscriptionPlan { Code = $"CSV-{Guid.NewGuid():N}", Name = "CSV filter plan", DeploymentKind = "cloud" };
            db.SubscriptionPlans.Add(plan);
            var subscriptionId = Guid.NewGuid();
            const string paymentReference = "verified-csv-payment-reference";
            var paidAt = new DateTimeOffset(2026, 10, 10, 0, 0, 0, TimeSpan.Zero);
            db.TenantSubscriptions.Add(new TenantSubscription
            {
                Id = subscriptionId, CompanyId = ownCompany.Id, PlanId = plan.Id, Status = "Active",
                PaymentReference = paymentReference, StartsAt = paidAt, EndsAt = paidAt.AddDays(365)
            });
            db.CompanyCheckoutOrders.Add(new CompanyCheckoutOrder
            {
                CompanyName = ownCompany.Name, Slug = ownCompany.Slug!, ContactEmail = ownCompany.ContactEmail!,
                OwnerName = "CSV Owner", OwnerEmail = "csv-owner@example.invalid", PlanId = plan.Id,
                TermDays = 365, SubtotalAmount = 1200m, Amount = 1200m, Currency = "TRY", Status = "Provisioned",
                PaymentReference = paymentReference, CompanyId = ownCompany.Id, PaidAt = paidAt,
                ExpiresAt = paidAt.AddDays(365)
            });
            db.TenantSubscriptions.Add(new TenantSubscription
            {
                CompanyId = otherCompany.Id, PlanId = plan.Id, Status = "Expired",
                StartsAt = new DateTimeOffset(2026, 10, 11, 0, 0, 0, TimeSpan.Zero),
                EndsAt = new DateTimeOffset(2026, 10, 12, 0, 0, 0, TimeSpan.Zero)
            });
            await db.SaveChangesAsync();
            _csvFilterPlanId = plan.Id;
            var logoDirectory = Path.Combine(_mediaPath, ownCompany.Id.ToString("N"));
            Directory.CreateDirectory(logoDirectory);
            await File.WriteAllBytesAsync(Path.Combine(logoDirectory, logoFileName), [137, 80, 78, 71]);
        }

        using (var denied = await SendAsUserAsync(HttpMethod.Get,
            $"/api/platform/companies/export.csv?q={Uri.EscapeDataString(marker)}", _userId, _companyId))
            Assert.Equal(HttpStatusCode.Forbidden, denied.StatusCode);

        using (var invalidSearch = await SendAsPlatformAdminAsync($"/api/platform/companies/export.csv?q={new string('x', 121)}"))
            Assert.Equal(HttpStatusCode.BadRequest, invalidSearch.StatusCode);
        using (var invalidFollowUp = await SendAsPlatformAdminAsync("/api/platform/companies/export.csv?followUp=tomorrow"))
            Assert.Equal(HttpStatusCode.BadRequest, invalidFollowUp.StatusCode);
        using (var invalidDateRange = await SendAsPlatformAdminAsync("/api/platform/companies?createdFrom=2026-10-12&createdTo=2026-10-10"))
            Assert.Equal(HttpStatusCode.BadRequest, invalidDateRange.StatusCode);
        using (var invalidSort = await SendAsPlatformAdminAsync("/api/platform/companies?sortBy=privateField"))
            Assert.Equal(HttpStatusCode.BadRequest, invalidSort.StatusCode);

        using (var filteredList = await SendAsPlatformAdminAsync($"/api/platform/companies?planId={_csvFilterPlanId}&createdFrom=2026-10-10&createdTo=2026-10-10&sortBy=createdAt&sortDirection=desc&pageSize=250"))
        {
            Assert.Equal(HttpStatusCode.OK, filteredList.StatusCode);
            using var payload = JsonDocument.Parse(await filteredList.Content.ReadAsStringAsync());
            Assert.Equal(250, payload.RootElement.GetProperty("pageSize").GetInt32());
            Assert.True(payload.RootElement.GetProperty("total").GetInt32() >= 1);
            var company = payload.RootElement.GetProperty("items")[0];
            Assert.Equal(_companyId, company.GetProperty("id").GetGuid());
            Assert.True(company.GetProperty("hasBrandLogo").GetBoolean());
            Assert.Equal(100m, company.GetProperty("verifiedMonthlyRecurringRevenue").GetDecimal());
            Assert.Equal("TRY", company.GetProperty("verifiedMrrCurrency").GetString());
        }

        using (var logo = await SendAsPlatformAdminAsync($"/api/platform/companies/{_companyId}/logo"))
        {
            Assert.Equal(HttpStatusCode.OK, logo.StatusCode);
            Assert.Equal("image/png", logo.Content.Headers.ContentType?.MediaType);
            Assert.Equal(new byte[] { 137, 80, 78, 71 }, await logo.Content.ReadAsByteArrayAsync());
        }
        using (var deniedLogo = await SendAsUserAsync(HttpMethod.Get,
            $"/api/platform/companies/{_companyId}/logo", _userId, _companyId))
            Assert.Equal(HttpStatusCode.Forbidden, deniedLogo.StatusCode);

        using var response = await SendAsPlatformAdminAsync($"/api/platform/companies/export.csv?q={Uri.EscapeDataString(marker)}&active=true&planId={_csvFilterPlanId}&createdFrom=2026-10-10&createdTo=2026-10-10&sortBy=createdAt&sortDirection=desc");
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.StartsWith("text/csv", response.Content.Headers.ContentType?.ToString(), StringComparison.OrdinalIgnoreCase);
        Assert.Contains("attachment", response.Content.Headers.ContentDisposition?.DispositionType ?? "", StringComparison.OrdinalIgnoreCase);
        Assert.EndsWith(".csv", response.Content.Headers.ContentDisposition?.FileNameStar ?? response.Content.Headers.ContentDisposition?.FileName ?? "", StringComparison.OrdinalIgnoreCase);
        var csv = await response.Content.ReadAsStringAsync();
        Assert.Contains("Firma", csv, StringComparison.Ordinal);
        Assert.Contains("Yetkili e-posta", csv, StringComparison.Ordinal);
        Assert.Contains("Doğrulanmış MRR", csv, StringComparison.Ordinal);
        Assert.Contains("\"100.00\";\"TRY\"", csv, StringComparison.Ordinal);
        Assert.Contains("\"Var\"", csv, StringComparison.Ordinal);
        Assert.Contains("\"'=2+2;CSV-", csv, StringComparison.Ordinal);
        Assert.Contains("csv-owner@example.invalid", csv, StringComparison.Ordinal);
        Assert.DoesNotContain("Excluded", csv, StringComparison.Ordinal);
        Assert.DoesNotContain("CheckoutTokenHash", csv, StringComparison.Ordinal);

        using var suspendedOnly = await SendAsPlatformAdminAsync("/api/platform/companies/export.csv?active=false");
        Assert.Equal(HttpStatusCode.OK, suspendedOnly.StatusCode);
        var suspendedCsv = await suspendedOnly.Content.ReadAsStringAsync();
        Assert.Contains("Excluded", suspendedCsv, StringComparison.Ordinal);
        Assert.DoesNotContain("csv-owner@example.invalid", suspendedCsv, StringComparison.Ordinal);
    }

    private Guid _csvFilterPlanId;

    [Fact]
    public async Task Platform_CRM_follow_up_digest_is_opt_in_daily_deduplicated_and_minimizes_lead_data()
    {
        var now = DateTimeOffset.UtcNow;
        var leadEmail = $"private-lead-{Guid.NewGuid():N}@example.invalid";
        var leadPhone = "+90-555-PRIVATE-CRM-DATA";
        var leadMessage = "PRIVATE-CRM-FREE-TEXT-MUST-NOT-LEAK";
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            var company = await db.Companies.SingleAsync(x => x.Id == _companyId);
            company.PlatformOwnerUserId = _userId;
            company.CustomerLifecycleStage = "Onboarding";
            company.PlatformNextFollowUpAt = now.AddHours(-2);
            var churnedCompany = await db.Companies.SingleAsync(x => x.Id == _otherCompanyId);
            churnedCompany.PlatformOwnerUserId = _userId;
            churnedCompany.CustomerLifecycleStage = "Churned";
            churnedCompany.PlatformNextFollowUpAt = now.AddHours(-1);
            db.PlatformDemoRequests.Add(new PlatformDemoRequest
            {
                CompanyName = "CRM reminder demo company", ContactName = "Private contact", Email = leadEmail,
                Phone = leadPhone, Message = leadMessage, Source = "security-acceptance", Status = "DemoScheduled",
                ConsentNoticeVersion = "acceptance-v1", AssignedAdminUserId = _userId, FollowUpAt = now.AddHours(-1)
            });
            await db.SaveChangesAsync();
        }

        var configValues = new Dictionary<string, string?>
        {
            ["Email:Smtp:Host"] = "127.0.0.1",
            ["Email:Smtp:Port"] = _smtpCapture.Port.ToString(CultureInfo.InvariantCulture),
            ["Email:Smtp:EnableSsl"] = "false",
            ["Email:FromAddress"] = "no-reply@example.invalid",
            ["Email:PublicBaseUrl"] = "https://portal.example.invalid",
            ["ASPNETCORE_ENVIRONMENT"] = "Development"
        };
        var disabledValues = new Dictionary<string, string?>(configValues)
        {
            ["Platform:CrmFollowUpEmailRemindersEnabled"] = "false"
        };
        var disabledConfiguration = new ConfigurationBuilder().AddInMemoryCollection(disabledValues).Build();
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var service = new PlatformCrmFollowUpEmailService(db, disabledConfiguration,
                scope.ServiceProvider.GetRequiredService<ILogger<PlatformCrmFollowUpEmailService>>());
            await service.RunOnceAsync(CancellationToken.None);
            Assert.Empty(_smtpCapture.Messages);
            Assert.Empty(await db.PlatformFollowUpEmailDigests.ToListAsync());
        }

        configValues["Platform:CrmFollowUpEmailRemindersEnabled"] = "true";
        var enabledConfiguration = new ConfigurationBuilder().AddInMemoryCollection(configValues).Build();
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var service = new PlatformCrmFollowUpEmailService(db, enabledConfiguration,
                scope.ServiceProvider.GetRequiredService<ILogger<PlatformCrmFollowUpEmailService>>());
            await service.RunOnceAsync(CancellationToken.None);
            Assert.Single(_smtpCapture.Messages);
            await service.RunOnceAsync(CancellationToken.None);
            Assert.Single(_smtpCapture.Messages);
            var digest = await db.PlatformFollowUpEmailDigests.SingleAsync(x => x.UserId == _userId);
            Assert.Equal("Sent", digest.Status);
            Assert.Equal(1, digest.AttemptCount);
        }

        var delivered = Assert.Single(_smtpCapture.Messages);
        Assert.Contains("Content-Transfer-Encoding: base64", delivered, StringComparison.OrdinalIgnoreCase);
        var bodySeparator = delivered.IndexOf("\n\n", StringComparison.Ordinal);
        Assert.True(bodySeparator >= 0, "Captured SMTP message must contain a MIME body separator.");
        var encodedBody = delivered[(bodySeparator + 2)..].Replace("\r", "", StringComparison.Ordinal)
            .Replace("\n", "", StringComparison.Ordinal);
        var decodedBody = Encoding.UTF8.GetString(Convert.FromBase64String(encodedBody));
        Assert.Contains("Security acceptance company", decodedBody, StringComparison.Ordinal);
        Assert.Contains("CRM reminder demo company", decodedBody, StringComparison.Ordinal);
        Assert.Contains("platform-admin.html", decodedBody, StringComparison.Ordinal);
        Assert.DoesNotContain(leadEmail, decodedBody, StringComparison.Ordinal);
        Assert.DoesNotContain(leadPhone, decodedBody, StringComparison.Ordinal);
        Assert.DoesNotContain(leadMessage, decodedBody, StringComparison.Ordinal);
        Assert.DoesNotContain("Other security acceptance company", decodedBody, StringComparison.Ordinal);
    }

    [Fact]
    public async Task Platform_admin_can_adjust_subscription_plan_and_dates_with_validation_and_audit()
    {
        var originalPlan = new SubscriptionPlan
        {
            Code = $"sub-old-{_companyId:N}", Name = "Original Cloud", DeploymentKind = "cloud", IsActive = true
        };
        var upgradedPlan = new SubscriptionPlan
        {
            Code = $"sub-new-{_companyId:N}", Name = "Upgraded Cloud", DeploymentKind = "cloud", IsActive = true
        };
        var subscriptionId = Guid.NewGuid();
        var now = DateTimeOffset.UtcNow;
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.SubscriptionPlans.AddRange(originalPlan, upgradedPlan);
            db.TenantSubscriptions.Add(new TenantSubscription
            {
                Id = subscriptionId, CompanyId = _companyId, PlanId = originalPlan.Id, Status = "Active", IsDemo = false,
                StartsAt = now.AddDays(-10), EndsAt = now.AddDays(20), PaymentReference = $"preserved-payment-{_companyId:N}"
            });
            db.CompanyCheckoutOrders.Add(new CompanyCheckoutOrder
            {
                Id = Guid.NewGuid(), CompanyName = "Acceptance Company", Slug = $"purchase-{_companyId:N}",
                ContactEmail = "billing@example.invalid", OwnerName = "Acceptance Owner", OwnerEmail = "owner@example.invalid",
                PlanId = originalPlan.Id, TermDays = 365, SubtotalAmount = 1299.50m, Amount = 1299.50m, Currency = "TRY", Status = "Provisioned",
                PaymentReference = $"verified-purchase-{_companyId:N}", CompanyId = _companyId,
                CreatedAt = now.AddDays(-11), ExpiresAt = now.AddDays(-10), PaidAt = now.AddDays(-10)
            });
            db.CompanyCheckoutOrders.Add(new CompanyCheckoutOrder
            {
                Id = Guid.NewGuid(), CompanyName = "Other Acceptance Company", Slug = $"purchase-other-{_otherCompanyId:N}",
                ContactEmail = "other-billing@example.invalid", OwnerName = "Other Acceptance Owner", OwnerEmail = "other-owner@example.invalid",
                PlanId = originalPlan.Id, TermDays = 30, SubtotalAmount = 9999m, Amount = 9999m, Currency = "TRY", Status = "Provisioned",
                PaymentReference = $"other-company-payment-{_otherCompanyId:N}", CompanyId = _otherCompanyId,
                CreatedAt = now.AddDays(-1), ExpiresAt = now, PaidAt = now
            });
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            await db.SaveChangesAsync();
        }

        using var csrfResponse = await SendAsPlatformAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));

        using (var companyDetail = await SendAsPlatformAdminAsync($"/api/platform/companies/{_companyId}"))
        {
            Assert.Equal(HttpStatusCode.OK, companyDetail.StatusCode);
            using var payload = JsonDocument.Parse(await companyDetail.Content.ReadAsStringAsync());
            var order = Assert.Single(payload.RootElement.GetProperty("checkoutOrders").EnumerateArray());
            Assert.Equal("Provisioned", order.GetProperty("status").GetString());
            Assert.Equal($"verified-purchase-{_companyId:N}", order.GetProperty("paymentReference").GetString());
            Assert.Equal(1299.50m, order.GetProperty("amount").GetDecimal());
            Assert.Equal(now.AddDays(-10).ToUnixTimeMilliseconds(), order.GetProperty("paidAt").GetDateTimeOffset().ToUnixTimeMilliseconds());
            Assert.False(order.TryGetProperty("checkoutPageUrlProtected", out _));
        }

        var invalidRangeRequest = new
        {
            planId = upgradedPlan.Id, startsAt = now.AddDays(25), endsAt = now.AddDays(20), note = "invalid range must be rejected"
        };
        using (var invalidRange = await SendAsPlatformAdminRequestAsync(HttpMethod.Put,
                   $"/api/platform/companies/{_companyId}/subscriptions/{subscriptionId}",
                   System.Net.Http.Json.JsonContent.Create(invalidRangeRequest), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, invalidRange.StatusCode);

        using (var missingReason = await SendAsPlatformAdminRequestAsync(HttpMethod.Put,
                   $"/api/platform/companies/{_companyId}/subscriptions/{subscriptionId}",
                   System.Net.Http.Json.JsonContent.Create(new { planId = upgradedPlan.Id, startsAt = now.AddDays(-2), endsAt = now.AddDays(90) }),
                   requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, missingReason.StatusCode);

        var editedStartsAt = now.AddDays(-2);
        var editedEndsAt = now.AddDays(90);
        var editRequest = new { planId = upgradedPlan.Id, startsAt = editedStartsAt, endsAt = editedEndsAt, note = "Customer success courtesy extension" };
        using (var denied = await SendAsUserAsync(HttpMethod.Put,
                   $"/api/platform/companies/{_companyId}/subscriptions/{subscriptionId}", _userId, _companyId,
                   System.Net.Http.Json.JsonContent.Create(editRequest)))
            Assert.Equal(HttpStatusCode.Forbidden, denied.StatusCode);
        using (var saved = await SendAsPlatformAdminRequestAsync(HttpMethod.Put,
                   $"/api/platform/companies/{_companyId}/subscriptions/{subscriptionId}",
                   System.Net.Http.Json.JsonContent.Create(editRequest), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, saved.StatusCode);
            using var payload = JsonDocument.Parse(await saved.Content.ReadAsStringAsync());
            Assert.False(payload.RootElement.GetProperty("unchanged").GetBoolean());
            Assert.Equal(upgradedPlan.Id, payload.RootElement.GetProperty("planId").GetGuid());
            Assert.Equal(editedStartsAt.ToUniversalTime().Ticks / 10, payload.RootElement.GetProperty("startsAt").GetDateTimeOffset().Ticks / 10);
            Assert.Equal(editedEndsAt.ToUniversalTime().Ticks / 10, payload.RootElement.GetProperty("endsAt").GetDateTimeOffset().Ticks / 10);
        }

        using (var retry = await SendAsPlatformAdminRequestAsync(HttpMethod.Put,
                   $"/api/platform/companies/{_companyId}/subscriptions/{subscriptionId}",
                   System.Net.Http.Json.JsonContent.Create(editRequest), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, retry.StatusCode);
            using var payload = JsonDocument.Parse(await retry.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("unchanged").GetBoolean());
        }

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var subscription = await db.TenantSubscriptions.SingleAsync(x => x.Id == subscriptionId);
            Assert.Equal("Active", subscription.Status);
            Assert.False(subscription.IsDemo);
            Assert.Equal($"preserved-payment-{_companyId:N}", subscription.PaymentReference);
            var auditEntries = await db.PlatformAuditEntries.Where(x => x.TargetId == subscriptionId && x.Action == "SubscriptionManuallyAdjusted").ToListAsync();
            var audit = Assert.Single(auditEntries);
            Assert.Contains(originalPlan.Id.ToString(), audit.Details, StringComparison.Ordinal);
            Assert.Contains(upgradedPlan.Id.ToString(), audit.Details, StringComparison.Ordinal);
            Assert.Contains("Customer success courtesy extension", audit.Details, StringComparison.Ordinal);
        }
    }

    [Fact]
    public async Task Platform_subscription_extension_uses_exact_end_date_and_safe_retries()
    {
        var plan = new SubscriptionPlan
        {
            Code = $"extend-{_companyId:N}", Name = "Extension retry acceptance", DeploymentKind = "cloud", IsActive = true
        };
        var subscriptionId = Guid.NewGuid();
        var demoSubscriptionId = Guid.NewGuid();
        var now = DateTimeOffset.UtcNow;
        var currentEnd = now.AddDays(14);
        var requestedEnd = now.AddDays(400);
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.SubscriptionPlans.Add(plan);
            db.TenantSubscriptions.Add(new TenantSubscription
            {
                Id = subscriptionId, CompanyId = _companyId, PlanId = plan.Id, Status = "Active", IsDemo = false,
                StartsAt = now.AddDays(-10), EndsAt = currentEnd, PaymentReference = $"already-verified-{_companyId:N}"
            });
            db.TenantSubscriptions.Add(new TenantSubscription
            {
                Id = demoSubscriptionId, CompanyId = _otherCompanyId, PlanId = plan.Id, Status = "Trial", IsDemo = true,
                StartsAt = now.AddDays(-3), EndsAt = currentEnd
            });
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            await db.SaveChangesAsync();
        }

        using var csrfResponse = await SendAsPlatformAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var request = new { endsAt = requestedEnd, note = "Approved complimentary renewal" };
        var route = $"/api/platform/companies/{_companyId}/subscription/extend";

        using (var first = await SendAsPlatformAdminRequestAsync(HttpMethod.Put, route,
                   System.Net.Http.Json.JsonContent.Create(request), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, first.StatusCode);
            using var payload = JsonDocument.Parse(await first.Content.ReadAsStringAsync());
            Assert.False(payload.RootElement.GetProperty("unchanged").GetBoolean());
            Assert.Equal(requestedEnd.ToUnixTimeMilliseconds(), payload.RootElement.GetProperty("endsAt").GetDateTimeOffset().ToUnixTimeMilliseconds());
        }

        using (var retry = await SendAsPlatformAdminRequestAsync(HttpMethod.Put, route,
                   System.Net.Http.Json.JsonContent.Create(request), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, retry.StatusCode);
            using var payload = JsonDocument.Parse(await retry.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("unchanged").GetBoolean());
            Assert.Equal(requestedEnd.ToUnixTimeMilliseconds(), payload.RootElement.GetProperty("endsAt").GetDateTimeOffset().ToUnixTimeMilliseconds());
        }

        using (var shortening = await SendAsPlatformAdminRequestAsync(HttpMethod.Put, route,
                   System.Net.Http.Json.JsonContent.Create(new { endsAt = currentEnd, note = "Must not shorten" }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, shortening.StatusCode);

        using (var demoExtension = await SendAsPlatformAdminRequestAsync(HttpMethod.Put,
                   $"/api/platform/companies/{_otherCompanyId}/subscription/extend",
                   System.Net.Http.Json.JsonContent.Create(new { endsAt = requestedEnd, note = "Complimentary demo extension" }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, demoExtension.StatusCode);
            using var payload = JsonDocument.Parse(await demoExtension.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("isDemo").GetBoolean());
            Assert.Equal("Trial", payload.RootElement.GetProperty("status").GetString());
        }

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var saved = await db.TenantSubscriptions.SingleAsync(x => x.Id == subscriptionId);
            Assert.Equal(requestedEnd.ToUnixTimeMilliseconds(), saved.EndsAt.ToUnixTimeMilliseconds());
            Assert.Equal($"already-verified-{_companyId:N}", saved.PaymentReference);
            var audit = await db.PlatformAuditEntries.Where(x => x.TargetId == subscriptionId && x.Action == "SubscriptionExtended").ToListAsync();
            var entry = Assert.Single(audit);
            Assert.Contains("Approved complimentary renewal", entry.Details, StringComparison.Ordinal);
            var demoSubscription = await db.TenantSubscriptions.SingleAsync(x => x.Id == demoSubscriptionId);
            Assert.True(demoSubscription.IsDemo);
            Assert.Equal("Trial", demoSubscription.Status);
            Assert.Equal(requestedEnd.ToUnixTimeMilliseconds(), demoSubscription.EndsAt.ToUnixTimeMilliseconds());
        }
    }

    [Fact]
    public async Task Platform_can_provision_a_paid_cloud_company_owner_and_retryable_invitation()
    {
        var plan = new SubscriptionPlan
        {
            Code = $"sale-{_companyId:N}", Name = "Paid Cloud provisioning acceptance", DeploymentKind = "cloud",
            IsActive = true, IsPublic = true
        };
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.SubscriptionPlans.Add(plan);
            db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            await db.SaveChangesAsync();
        }

        using var csrfResponse = await SendAsPlatformAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var email = $"paid-owner-{Guid.NewGuid():N}@example.invalid";
        var slug = $"paid-{Guid.NewGuid():N}";
        var requestBody = new
        {
            companyName = "Paid Cloud Acceptance Company", slug, contactEmail = email,
            ownerName = "Paid Cloud Owner", ownerEmail = email, planId = plan.Id,
            termDays = 365, paymentReference = $"acceptance-{Guid.NewGuid():N}", paymentVerified = true
        };

        using (var created = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, "/api/platform/companies",
                   System.Net.Http.Json.JsonContent.Create(requestBody), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, created.StatusCode);
            using var payload = JsonDocument.Parse(await created.Content.ReadAsStringAsync());
            Assert.Equal(slug, payload.RootElement.GetProperty("slug").GetString());
            Assert.Equal(365, (payload.RootElement.GetProperty("endsAt").GetDateTimeOffset() -
                payload.RootElement.GetProperty("startsAt").GetDateTimeOffset()).Days);
            Assert.True(payload.RootElement.GetProperty("invitationSent").GetBoolean());
        }

        Guid companyId;
        Guid ownerId;
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var company = await db.Companies.SingleAsync(x => x.Slug == slug);
            Assert.True(company.SecurityRequireMfa, "Platform-created paid Cloud companies must require first-login MFA enrollment, just like checkout-created companies.");
            companyId = company.Id;
            var membership = await db.CompanyMemberships.SingleAsync(x => x.CompanyId == companyId);
            ownerId = membership.UserId;
            Assert.Equal("owner", membership.RoleKey);
            var owner = await db.Users.SingleAsync(x => x.Id == ownerId);
            Assert.Equal(email, owner.Email);
            Assert.False(owner.EmailConfirmed);
            var subscription = await db.TenantSubscriptions.SingleAsync(x => x.CompanyId == companyId);
            Assert.Equal("Active", subscription.Status);
            Assert.False(subscription.IsDemo);
            Assert.Equal(requestBody.paymentReference, subscription.PaymentReference);
        }

        Assert.Contains(_smtpCapture.Messages, message => message.Contains(email, StringComparison.OrdinalIgnoreCase));
        using (var resent = await SendAsPlatformAdminRequestAsync(HttpMethod.Post,
                   $"/api/platform/companies/{companyId}/owner-invitation/resend", new StringContent("{}", Encoding.UTF8, "application/json"),
                   requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, resent.StatusCode);
            using var payload = JsonDocument.Parse(await resent.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("invitationSent").GetBoolean());
        }
        using (var duplicateSlug = await SendAsPlatformAdminRequestAsync(HttpMethod.Post, "/api/platform/companies",
                   System.Net.Http.Json.JsonContent.Create(requestBody), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, duplicateSlug.StatusCode);

        Assert.All(_smtpCapture.Messages, message =>
            Assert.Contains($"https://{slug}.envantertr.com/", DecodeMimeBody(message), StringComparison.Ordinal));
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var confirmedOwner = await db.Users.SingleAsync(x => x.Id == ownerId);
            confirmedOwner.EmailConfirmed = true;
            await db.SaveChangesAsync();
        }
        using (var confirmedResend = await SendAsPlatformAdminRequestAsync(HttpMethod.Post,
                   $"/api/platform/companies/{companyId}/owner-invitation/resend", new StringContent("{}", Encoding.UTF8, "application/json"),
                   requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.OK, confirmedResend.StatusCode);
        var ownerAccessBody = DecodeMimeBody(_smtpCapture.Messages.Last());
        Assert.Contains("Şirket sahibi", ownerAccessBody, StringComparison.Ordinal);
        Assert.Contains($"https://{slug}.envantertr.com/", ownerAccessBody, StringComparison.Ordinal);

        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            Assert.Equal(1, await db.Companies.CountAsync(x => x.Slug == slug));
            Assert.Equal(1, await db.CompanyMemberships.CountAsync(x => x.CompanyId == companyId && x.UserId == ownerId));
            Assert.Equal(1, await db.TenantSubscriptions.CountAsync(x => x.CompanyId == companyId));
        }
    }

