        Assert.Equal(2, await verifyDb.AuditEntries.CountAsync(item => item.CompanyId == _companyId &&
            (item.TargetId == _ownAssetId || item.TargetId == secondAssetId) && item.Action == "BulkTransferred"));
    }

    [Fact]
    public async Task Bulk_asset_audit_is_atomic_company_scoped_authorized_and_audited()
    {
        using var csrfResponse = await SendAsAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var secondAssetId = Guid.NewGuid();
        var auditDate = DateOnly.FromDateTime(DateTime.UtcNow);
        var nextAuditOn = auditDate.AddDays(30);
        await using (var setupScope = _factory!.Services.CreateAsyncScope())
        {
            var db = setupScope.ServiceProvider.GetRequiredService<AppDbContext>();
            var first = await db.Assets.SingleAsync(asset => asset.CompanyId == _companyId && asset.Id == _ownAssetId);
            var categoryId = first.CategoryId;
            first.NextAuditOn = null;
            db.Assets.Add(new Asset
            {
                Id = secondAssetId, CompanyId = _companyId, AssetTag = $"BULK-AUDIT-{_userId:N}",
                Name = "Second bulk audit asset", CategoryId = categoryId
            });
            await db.SaveChangesAsync();
        }

        var successPayload = new
        {
            assetIds = new[] { _ownAssetId, secondAssetId },
            auditDate,
            nextAuditOn,
            notes = "Quarterly physical audit"
        };
        using (var missingCsrf = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(successPayload)))
            Assert.Equal(HttpStatusCode.BadRequest, missingCsrf.StatusCode);
        await SetCompanyRoleAsync("viewer");
        using (var forbidden = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "viewer",
                   System.Net.Http.Json.JsonContent.Create(successPayload), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Forbidden, forbidden.StatusCode);
        await SetCompanyRoleAsync("admin");
        using (var duplicateIds = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { assetIds = new[] { _ownAssetId, _ownAssetId }, auditDate }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, duplicateIds.StatusCode);
        using (var invalidAuditDate = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { assetIds = new[] { _ownAssetId }, auditDate = auditDate.AddDays(2) }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, invalidAuditDate.StatusCode);
        using (var invalidNextAuditDate = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { assetIds = new[] { _ownAssetId }, auditDate, nextAuditOn = auditDate.AddDays(-1) }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, invalidNextAuditDate.StatusCode);
        using (var crossTenant = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { assetIds = new[] { _ownAssetId, _otherCompanyAssetId }, auditDate }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.NotFound, crossTenant.StatusCode);
        await using (var verifyNoPartialWrite = _factory.Services.CreateAsyncScope())
        {
            var db = verifyNoPartialWrite.ServiceProvider.GetRequiredService<AppDbContext>();
            Assert.Null(await db.Assets.Where(asset => asset.CompanyId == _companyId && asset.Id == _ownAssetId)
                .Select(asset => asset.NextAuditOn).SingleAsync());
            Assert.Null(await db.Assets.Where(asset => asset.CompanyId == _companyId && asset.Id == secondAssetId)
                .Select(asset => asset.NextAuditOn).SingleAsync());
            Assert.Equal(0, await db.AssetEvents.CountAsync(item => item.CompanyId == _companyId &&
                (item.AssetId == _ownAssetId || item.AssetId == secondAssetId) && item.EventType == "Audited" &&
                EF.Functions.Like(item.Details!, "%Quarterly physical audit%")));
        }

        using (var recorded = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(successPayload), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, recorded.StatusCode);
            using var payload = JsonDocument.Parse(await recorded.Content.ReadAsStringAsync());
            Assert.Equal(2, payload.RootElement.GetProperty("recorded").GetInt32());
            Assert.Equal(auditDate, DateOnly.Parse(payload.RootElement.GetProperty("auditDate").GetString()!));
            Assert.Equal(nextAuditOn, DateOnly.Parse(payload.RootElement.GetProperty("nextAuditOn").GetString()!));
        }

        await using var verifyScope = _factory.Services.CreateAsyncScope();
        var verifyDb = verifyScope.ServiceProvider.GetRequiredService<AppDbContext>();
        var saved = await verifyDb.Assets.AsNoTracking().Where(asset => asset.CompanyId == _companyId &&
            (asset.Id == _ownAssetId || asset.Id == secondAssetId)).ToListAsync();
        Assert.All(saved, item => Assert.Equal(nextAuditOn, item.NextAuditOn));
        var events = await verifyDb.AssetEvents.AsNoTracking().Where(item => item.CompanyId == _companyId &&
            (item.AssetId == _ownAssetId || item.AssetId == secondAssetId) && item.EventType == "Audited" &&
            EF.Functions.Like(item.Details!, "%Quarterly physical audit%")).ToListAsync();
        Assert.Equal(2, events.Count);
        Assert.All(events, item =>
        {
            Assert.Equal(_userId, item.ActorUserId);
            Assert.Contains(auditDate.ToString("yyyy-MM-dd"), item.Details, StringComparison.Ordinal);
            Assert.Contains("Quarterly physical audit", item.Details, StringComparison.Ordinal);
            Assert.Contains(nextAuditOn.ToString("yyyy-MM-dd"), item.Details, StringComparison.Ordinal);
        });
        Assert.Equal(2, await verifyDb.AuditEntries.CountAsync(item => item.CompanyId == _companyId &&
            (item.TargetId == _ownAssetId || item.TargetId == secondAssetId) && item.Action == "BulkAudited"));

        var unacceptablePayload = new
        {
            assetIds = new[] { _ownAssetId, secondAssetId }, auditDate, nextAuditOn = (DateOnly?)null,
            notes = "Cracked casing found", outcome = "Unacceptable", issueDescription = "Battery cover cracked; remove from service."
        };
        using (var missingFinding = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { assetIds = unacceptablePayload.assetIds, auditDate, outcome = "Unacceptable" }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, missingFinding.StatusCode);
        using (var unacceptable = await SendAsRoleAsync(HttpMethod.Post, "/api/assets/bulk-audit", "admin",
                   System.Net.Http.Json.JsonContent.Create(unacceptablePayload), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, unacceptable.StatusCode);
            using var payload = JsonDocument.Parse(await unacceptable.Content.ReadAsStringAsync());
            Assert.Equal("Unacceptable", payload.RootElement.GetProperty("outcome").GetString());
            Assert.Equal(2, payload.RootElement.GetProperty("recorded").GetInt32());
        }
        var unacceptableEvents = await verifyDb.AssetEvents.AsNoTracking().Where(item => item.CompanyId == _companyId &&
            (item.AssetId == _ownAssetId || item.AssetId == secondAssetId) && item.EventType == "AuditUnacceptable" &&
            EF.Functions.Like(item.Details!, "%Battery cover cracked; remove from service.%")).ToListAsync();
        Assert.Equal(2, unacceptableEvents.Count);
        Assert.All(unacceptableEvents, item => Assert.Equal(_userId, item.ActorUserId));
        Assert.Equal(2, await verifyDb.AuditEntries.CountAsync(item => item.CompanyId == _companyId &&
            (item.TargetId == _ownAssetId || item.TargetId == secondAssetId) && item.Action == "BulkAuditUnacceptable"));
        Assert.All(await verifyDb.Assets.AsNoTracking().Where(asset => asset.CompanyId == _companyId &&
            (asset.Id == _ownAssetId || asset.Id == secondAssetId)).ToListAsync(), item => Assert.Null(item.NextAuditOn));
    }

    [Fact]
    public async Task Asset_archive_restore_is_authorized_tenant_scoped_and_audited()
    {
        using var csrfResponse = await SendAsAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));

        await SetCompanyRoleAsync("viewer");
        using (var readOnly = await SendAsRoleAsync(HttpMethod.Post, $"/api/assets/{_ownAssetId}/restore", "viewer",
                   System.Net.Http.Json.JsonContent.Create(new { status = AssetStatuses.Available, note = "Restore attempt" }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Forbidden, readOnly.StatusCode);
        await SetCompanyRoleAsync("admin");
        using (var crossTenant = await SendAsRoleAsync(HttpMethod.Post, $"/api/assets/{_otherCompanyAssetId}/restore", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { status = AssetStatuses.Available, note = "Cross tenant" }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.NotFound, crossTenant.StatusCode);
        using (var archived = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_ownAssetId}/status", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { status = AssetStatuses.Archived }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.OK, archived.StatusCode);

        using (var restored = await SendAsRoleAsync(HttpMethod.Post, $"/api/assets/{_ownAssetId}/restore", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { status = AssetStatuses.Available, note = "Archive restore acceptance" }), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, restored.StatusCode);
            using var payload = JsonDocument.Parse(await restored.Content.ReadAsStringAsync());
            Assert.Equal(AssetStatuses.Available, payload.RootElement.GetProperty("status").GetString());
        }

        using var detail = await SendAsAdminAsync($"/api/assets/{_ownAssetId}");
        Assert.Equal(HttpStatusCode.OK, detail.StatusCode);
        using var detailPayload = JsonDocument.Parse(await detail.Content.ReadAsStringAsync());
        Assert.Equal(AssetStatuses.Available, detailPayload.RootElement.GetProperty("asset").GetProperty("status").GetString());
        Assert.Contains(detailPayload.RootElement.GetProperty("history").EnumerateArray(), item =>
            item.GetProperty("eventType").GetString() == "StatusChanged" && item.GetProperty("details").GetString()!.Contains("Archive restore acceptance", StringComparison.Ordinal));

        await using var scope = _factory!.Services.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        Assert.Contains(await db.AuditEntries.AsNoTracking().Where(item => item.CompanyId == _companyId && item.TargetId == _ownAssetId).ToListAsync(),
            item => item.Action == "Restored" && item.ActorUserId == _userId && item.Details!.Contains("Archive restore acceptance", StringComparison.Ordinal));

        var lockedAssetId = Guid.NewGuid();
        await using (var lockScope = _factory!.Services.CreateAsyncScope())
        {
            var lockDb = lockScope.ServiceProvider.GetRequiredService<AppDbContext>();
            var categoryId = await lockDb.Assets.AsNoTracking()
                .Where(item => item.CompanyId == _companyId && item.Id == _ownAssetId)
                .Select(item => item.CategoryId).SingleAsync();
            lockDb.Assets.Add(new Asset
            {
                Id = lockedAssetId, CompanyId = _companyId, AssetTag = $"ARCHIVE-LOCK-{Guid.NewGuid():N}",
                Name = "Archived asset restore lock", CategoryId = categoryId,
                Status = AssetStatuses.Archived
            });
            await lockDb.SaveChangesAsync();
        }

        await using (var maintenanceScope = _factory!.Services.CreateAsyncScope())
        {
            var maintenanceDb = maintenanceScope.ServiceProvider.GetRequiredService<AppDbContext>();
            var lockedAsset = await maintenanceDb.Assets.SingleAsync(item => item.CompanyId == _companyId && item.Id == lockedAssetId);
            maintenanceDb.AssetMaintenances.Add(new AssetMaintenance
            {
                CompanyId = _companyId, AssetId = lockedAssetId, ActorUserId = _userId,
                MaintenanceType = "Restore lock acceptance", StartedOn = DateOnly.FromDateTime(DateTime.UtcNow),
                Status = "InProgress"
            });
            await maintenanceDb.SaveChangesAsync();
        }

        using (var maintenanceLock = await SendAsRoleAsync(HttpMethod.Post, $"/api/assets/{lockedAssetId}/restore", "admin",
                   System.Net.Http.Json.JsonContent.Create(new { status = AssetStatuses.Available, note = "Maintenance lock" }), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, maintenanceLock.StatusCode);

        await using var lockedVerificationScope = _factory!.Services.CreateAsyncScope();
        var lockedVerificationDb = lockedVerificationScope.ServiceProvider.GetRequiredService<AppDbContext>();
        var stillLocked = await lockedVerificationDb.Assets.AsNoTracking()
            .SingleAsync(item => item.CompanyId == _companyId && item.Id == lockedAssetId);
        Assert.Equal(AssetStatuses.Archived, stillLocked.Status);
        Assert.DoesNotContain(await lockedVerificationDb.AuditEntries.AsNoTracking()
                .Where(item => item.CompanyId == _companyId && item.TargetId == lockedAssetId).ToListAsync(),
            item => item.Action == "Restored");
    }

    [Fact]
    public async Task Asset_single_edit_is_tenant_scoped_version_checked_and_written_to_history()
    {
        Asset current;
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            current = await db.Assets.AsNoTracking().SingleAsync(item => item.CompanyId == _companyId && item.Id == _ownAssetId);
        }

        using var csrfResponse = await SendAsAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var updatedName = $"{current.Name} edited";
        object Request(DateTimeOffset expectedUpdatedAt, Guid categoryId, string? name = null) => new
        {
            assetTag = current.AssetTag,
            name = name ?? updatedName,
            categoryId,
            brandId = current.BrandId,
            modelId = current.ModelId,
            serialNumber = current.SerialNumber,
            location = current.Location,
            purchaseDate = current.PurchaseDate?.ToString("yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture),
            warrantyExpiresAt = current.WarrantyExpiresAt?.ToString("yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture),
            purchaseCost = current.PurchaseCost,
            currency = current.Currency,
            expectedUpdatedAt,
            isRequestable = current.IsRequestable,
            isByod = current.IsByod,
            defaultLocationCatalogId = current.DefaultLocationCatalogId,
            notes = current.Notes
        };

        using (var missingCsrf = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_ownAssetId}", "admin",
                   System.Net.Http.Json.JsonContent.Create(Request(current.UpdatedAt, current.CategoryId))))
            Assert.Equal(HttpStatusCode.BadRequest, missingCsrf.StatusCode);
        await SetCompanyRoleAsync("viewer");
        using (var readOnly = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_ownAssetId}", "viewer",
                   System.Net.Http.Json.JsonContent.Create(Request(current.UpdatedAt, current.CategoryId)), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Forbidden, readOnly.StatusCode);
        await SetCompanyRoleAsync("admin");
        using (var crossTenant = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_otherCompanyAssetId}", "admin",
                   System.Net.Http.Json.JsonContent.Create(Request(current.UpdatedAt, current.CategoryId)), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.NotFound, crossTenant.StatusCode);
        using (var invalidCategory = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_ownAssetId}", "admin",
                   System.Net.Http.Json.JsonContent.Create(Request(current.UpdatedAt, Guid.NewGuid())), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, invalidCategory.StatusCode);
        using (var staleVersion = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_ownAssetId}", "admin",
                   System.Net.Http.Json.JsonContent.Create(Request(current.UpdatedAt.AddTicks(-1), current.CategoryId)), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, staleVersion.StatusCode);

        using (var updated = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_ownAssetId}", "admin",
                   System.Net.Http.Json.JsonContent.Create(Request(current.UpdatedAt, current.CategoryId)), requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.OK, updated.StatusCode);
            using var payload = JsonDocument.Parse(await updated.Content.ReadAsStringAsync());
            Assert.True(payload.RootElement.GetProperty("changed").GetBoolean());
        }
        using (var replay = await SendAsRoleAsync(HttpMethod.Patch, $"/api/assets/{_ownAssetId}", "admin",
                   System.Net.Http.Json.JsonContent.Create(Request(current.UpdatedAt, current.CategoryId, "Stale overwrite")), requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, replay.StatusCode);

        using var detail = await SendAsAdminAsync($"/api/assets/{_ownAssetId}");
        Assert.Equal(HttpStatusCode.OK, detail.StatusCode);
        using var detailPayload = JsonDocument.Parse(await detail.Content.ReadAsStringAsync());
        Assert.Equal(updatedName, detailPayload.RootElement.GetProperty("asset").GetProperty("name").GetString());
        Assert.Contains(detailPayload.RootElement.GetProperty("history").EnumerateArray(), item =>
            item.GetProperty("eventType").GetString() == "Updated" && item.GetProperty("details").GetString()!.Contains("ad", StringComparison.Ordinal));

        await using var verifyScope = _factory.Services.CreateAsyncScope();
        var verifyDb = verifyScope.ServiceProvider.GetRequiredService<AppDbContext>();
        var saved = await verifyDb.Assets.AsNoTracking().SingleAsync(item => item.CompanyId == _companyId && item.Id == _ownAssetId);
        Assert.Equal(updatedName, saved.Name);
        Assert.True(saved.UpdatedAt > current.UpdatedAt);
    }

    [Fact]
    public async Task Asset_attachment_upload_download_and_delete_are_authorized_tenant_scoped_and_audited()
    {
        using var csrfResponse = await SendAsAdminAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        var pdfBytes = Encoding.ASCII.GetBytes("%PDF-1.7\nasset attachment acceptance\n%%EOF");

        using (var invalidFile = await SendAssetAttachmentUploadAsync(_ownAssetId, [1, 2, 3], "invalid.pdf", requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.BadRequest, invalidFile.StatusCode);
        using (var crossTenantUpload = await SendAssetAttachmentUploadAsync(_otherCompanyAssetId, pdfBytes, "foreign.pdf", requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.NotFound, crossTenantUpload.StatusCode);
        using (var missingCsrf = await SendAsUserAsync(HttpMethod.Post, $"/api/assets/{_ownAssetId}/attachments", _userId, _companyId,
                   new MultipartFormDataContent(), requestToken: null, antiforgeryCookie: null))
            Assert.Equal(HttpStatusCode.BadRequest, missingCsrf.StatusCode);

        await SetCompanyRoleAsync("viewer");
        using (var readOnlyUpload = await SendAssetAttachmentUploadAsync(_ownAssetId, pdfBytes, "denied.pdf", requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Forbidden, readOnlyUpload.StatusCode);
        await SetCompanyRoleAsync("admin");

        using var upload = await SendAssetAttachmentUploadAsync(_ownAssetId, pdfBytes, "inspection-receipt.pdf", requestToken, antiforgeryCookie);
        Assert.Equal(HttpStatusCode.Created, upload.StatusCode);
        using var uploadPayload = JsonDocument.Parse(await upload.Content.ReadAsStringAsync());
        var attachmentId = uploadPayload.RootElement.GetProperty("id").GetGuid();
        var attachmentPath = Path.Combine(_mediaPath, _companyId.ToString("N"), "assets", _ownAssetId.ToString("N"), $"{attachmentId:N}.pdf");
        Assert.True(File.Exists(attachmentPath));

        using (var download = await SendAsAdminAsync($"/api/assets/{_ownAssetId}/attachments/{attachmentId}/file?download=true"))
        {
            Assert.Equal(HttpStatusCode.OK, download.StatusCode);
            Assert.Equal(pdfBytes, await download.Content.ReadAsByteArrayAsync());
        }
        using (var crossTenantDownload = await SendAsAdminAsync($"/api/assets/{_otherCompanyAssetId}/attachments/{attachmentId}/file"))
            Assert.Equal(HttpStatusCode.NotFound, crossTenantDownload.StatusCode);
        await SetCompanyRoleAsync("viewer");
        using (var readOnlyDelete = await SendAsUserAsync(HttpMethod.Delete, $"/api/assets/{_ownAssetId}/attachments/{attachmentId}",
                   _userId, _companyId, requestToken: requestToken, antiforgeryCookie: antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Forbidden, readOnlyDelete.StatusCode);
        await SetCompanyRoleAsync("admin");
        using (var crossTenantDelete = await SendAsUserAsync(HttpMethod.Delete, $"/api/assets/{_otherCompanyAssetId}/attachments/{attachmentId}",
                   _userId, _companyId, requestToken: requestToken, antiforgeryCookie: antiforgeryCookie))
            Assert.Equal(HttpStatusCode.NotFound, crossTenantDelete.StatusCode);
        using (var removed = await SendAsUserAsync(HttpMethod.Delete, $"/api/assets/{_ownAssetId}/attachments/{attachmentId}",
                   _userId, _companyId, requestToken: requestToken, antiforgeryCookie: antiforgeryCookie))
            Assert.Equal(HttpStatusCode.NoContent, removed.StatusCode);
        Assert.False(File.Exists(attachmentPath));
        using (var missingAfterDelete = await SendAsAdminAsync($"/api/assets/{_ownAssetId}/attachments/{attachmentId}/file"))
            Assert.Equal(HttpStatusCode.NotFound, missingAfterDelete.StatusCode);
        using var detail = await SendAsAdminAsync($"/api/assets/{_ownAssetId}");
        using var detailPayload = JsonDocument.Parse(await detail.Content.ReadAsStringAsync());
        Assert.DoesNotContain(detailPayload.RootElement.GetProperty("attachments").EnumerateArray(),
            item => item.GetProperty("id").GetGuid() == attachmentId);
        Assert.Contains(detailPayload.RootElement.GetProperty("history").EnumerateArray(), item => item.GetProperty("eventType").GetString() == "AttachmentAdded");
        Assert.Contains(detailPayload.RootElement.GetProperty("history").EnumerateArray(), item => item.GetProperty("eventType").GetString() == "AttachmentRemoved");

        var tenMiBImage = new byte[10_485_760];
        new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 }.CopyTo(tenMiBImage, 0);
        Guid maxSizePhotoId;
        using (var maxSizeUpload = await SendAssetAttachmentUploadAsync(_ownAssetId, tenMiBImage, "maximum-size.png", requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, maxSizeUpload.StatusCode);
            using var maxSizePayload = JsonDocument.Parse(await maxSizeUpload.Content.ReadAsStringAsync());
            Assert.Equal(10_485_760, maxSizePayload.RootElement.GetProperty("length").GetInt64());
            maxSizePhotoId = maxSizePayload.RootElement.GetProperty("id").GetGuid();
        }
        for (var index = 2; index <= 29; index++)
        {
            using var belowLimit = await SendAssetAttachmentUploadAsync(_ownAssetId, pdfBytes, $"attachment-{index}.pdf", requestToken, antiforgeryCookie);
            Assert.Equal(HttpStatusCode.Created, belowLimit.StatusCode);
        }
        var newestImage = new byte[] { 137, 80, 78, 71, 13, 10, 26, 10, 0 };
        Guid newestPhotoId;
        using (var newerPhotoUpload = await SendAssetAttachmentUploadAsync(_ownAssetId, newestImage, "newest-photo.png", requestToken, antiforgeryCookie))
        {
            Assert.Equal(HttpStatusCode.Created, newerPhotoUpload.StatusCode);
            using var newerPhotoPayload = JsonDocument.Parse(await newerPhotoUpload.Content.ReadAsStringAsync());
            Assert.Equal("image/png", newerPhotoPayload.RootElement.GetProperty("contentType").GetString());
            newestPhotoId = newerPhotoPayload.RootElement.GetProperty("id").GetGuid();
            Assert.NotEqual(maxSizePhotoId, newestPhotoId);
        }
        using (var overCount = await SendAssetAttachmentUploadAsync(_ownAssetId, pdfBytes, "attachment-31.pdf", requestToken, antiforgeryCookie))
            Assert.Equal(HttpStatusCode.Conflict, overCount.StatusCode);

        using (var assetList = await SendAsAdminAsync("/api/assets?page=1&pageSize=200"))
        {
            Assert.Equal(HttpStatusCode.OK, assetList.StatusCode);
            using var assetListPayload = JsonDocument.Parse(await assetList.Content.ReadAsStringAsync());
            var listedAsset = Assert.Single(assetListPayload.RootElement.GetProperty("items").EnumerateArray(),
                item => item.GetProperty("id").GetGuid() == _ownAssetId);
            Assert.Equal(newestPhotoId, listedAsset.GetProperty("photoAttachmentId").GetGuid());
        }

        await using var scope = _factory!.Services.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        Assert.False(await db.AssetAttachments.AnyAsync(item => item.CompanyId == _companyId && item.AssetId == _ownAssetId && item.Id == attachmentId));
        var auditActions = await db.AuditEntries.AsNoTracking().Where(item => item.CompanyId == _companyId &&
            item.TargetType == "Asset" && item.TargetId == _ownAssetId).Select(item => item.Action).ToListAsync();
        Assert.Contains("AttachmentAdded", auditActions);
        Assert.Contains("AttachmentRemoved", auditActions);
    }

    [Fact]
    public async Task Asset_detail_returns_company_scoped_book_value_and_null_when_required_inputs_are_missing()
    {
        var today = DateOnly.FromDateTime(DateTime.UtcNow);
        await using (var scope = _factory!.Services.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
