        using (var noCost = await SendAsAdminAsync($"/api/assets/{_ownAssetId}"))
        {
            using var payload = JsonDocument.Parse(await noCost.Content.ReadAsStringAsync());
            var valuation = payload.RootElement.GetProperty("valuation");
