            Assert.Equal(HttpStatusCode.NotFound, crossTenantUpload.StatusCode);
        using (var foreignAttachmentOnOwnMaintenance = await SendAsAdminAsync($"/api/maintenances/{maintenanceId}/attachments/{otherAttachmentId}/file"))
