        using var csvResponse = await SendAsAdminAsync($"/api/asset-orders/export.csv?q={Uri.EscapeDataString(orderNumber)}&status=Ordered&from={today.AddDays(-2):yyyy-MM-dd}&to={today:yyyy-MM-dd}");
