            var user = await users.FindByIdAsync(_userId.ToString());
            Assert.NotNull(user);
            var passwordResult = await users.AddPasswordAsync(user, password);
            Assert.True(passwordResult.Succeeded, string.Join("; ", passwordResult.Errors.Select(error => error.Description)));

            var db = services.GetRequiredService<AppDbContext>();
            db.Companies.Add(new Company { Id = additionalCompanyId, Name = "Authorized second company", Slug = $"authorized-{additionalCompanyId:N}", IsActive = true });
            db.CompanyMemberships.Add(new CompanyMembership { CompanyId = additionalCompanyId, UserId = _userId, RoleKey = "owner" });
            if (!await db.PlatformAdministrators.AnyAsync(entry => entry.UserId == _userId))
                db.PlatformAdministrators.Add(new PlatformAdministrator { UserId = _userId });
            await db.SaveChangesAsync();
        }

        using var loginClient = _factory.CreateClient(new WebApplicationFactoryClientOptions { HandleCookies = false });
        using var csrfResponse = await loginClient.GetAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, csrfResponse.StatusCode);
        using var csrfPayload = JsonDocument.Parse(await csrfResponse.Content.ReadAsStringAsync());
        var requestToken = csrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var antiforgeryCookie = csrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));

        using (var chooserResponse = await SendAnonymousLoginAsync(loginClient, email, password, null,
            requestToken, antiforgeryCookie, companyId: null))
        using (var chooser = JsonDocument.Parse(await chooserResponse.Content.ReadAsStringAsync()))
        {
            Assert.Equal(HttpStatusCode.Conflict, chooserResponse.StatusCode);
            var companies = chooser.RootElement.GetProperty("companies").EnumerateArray().ToArray();
            Assert.Equal(2, companies.Length);
            Assert.Contains(companies, company => company.GetProperty("id").GetGuid() == _companyId);
            Assert.Contains(companies, company => company.GetProperty("id").GetGuid() == additionalCompanyId);
            Assert.DoesNotContain(companies, company => company.GetProperty("id").GetGuid() == _otherCompanyId);
            Assert.DoesNotContain(companies, company => company.GetProperty("name").GetString() == "Other security acceptance company");
        }

        using var cookieFactory = new WebApplicationFactory<Program>().WithWebHostBuilder(builder =>
        {
            builder.UseEnvironment("Development");
            builder.ConfigureAppConfiguration((_, configuration) => configuration.AddInMemoryCollection(
                new Dictionary<string, string?>
                {
                    ["ConnectionStrings:EnvanterTR"] = Environment.GetEnvironmentVariable("ENVANTERTR_SECURITY_TEST_CONNECTION"),
                    ["Storage:CompanyMediaPath"] = _mediaPath,
                    ["TenantRouting:RootDomain"] = "envantertr.com"
                }));
            builder.ConfigureTestServices(services => services.PostConfigure<SecurityStampValidatorOptions>(options =>
                options.ValidationInterval = TimeSpan.Zero));
        });
        using var authenticatedClient = cookieFactory.CreateClient();
        using var authenticatedCsrfResponse = await authenticatedClient.GetAsync("/api/session/csrf");
        Assert.Equal(HttpStatusCode.OK, authenticatedCsrfResponse.StatusCode);
        using var authenticatedCsrfPayload = JsonDocument.Parse(await authenticatedCsrfResponse.Content.ReadAsStringAsync());
        var authenticatedRequestToken = authenticatedCsrfPayload.RootElement.GetProperty("requestToken").GetString()!;
        var authenticatedAntiforgeryCookie = authenticatedCsrfResponse.Headers.GetValues("Set-Cookie")
            .Select(value => value.Split(';', 2)[0])
            .First(value => value.Contains('=') && value.Split('=', 2)[0].Contains("Antiforgery", StringComparison.OrdinalIgnoreCase));
        using (var authorizedChoice = await SendAnonymousLoginAsync(authenticatedClient, email, password, null,
            authenticatedRequestToken, authenticatedAntiforgeryCookie, companyId: additionalCompanyId))
        using (var session = JsonDocument.Parse(await authorizedChoice.Content.ReadAsStringAsync()))
        {
            Assert.Equal(HttpStatusCode.OK, authorizedChoice.StatusCode);
            Assert.Equal(additionalCompanyId, session.RootElement.GetProperty("companyId").GetGuid());

            using var activeSession = await authenticatedClient.GetAsync("/api/session");
            Assert.Equal(HttpStatusCode.OK, activeSession.StatusCode);
            using var activeSessionPayload = JsonDocument.Parse(await activeSession.Content.ReadAsStringAsync());
            var accessibleCompanies = activeSessionPayload.RootElement.GetProperty("availableCompanies").EnumerateArray().ToArray();
            Assert.Equal(2, accessibleCompanies.Length);
            Assert.Contains(accessibleCompanies, company => company.GetProperty("id").GetGuid() == _companyId);
            Assert.Contains(accessibleCompanies, company => company.GetProperty("id").GetGuid() == additionalCompanyId);
            Assert.DoesNotContain(accessibleCompanies, company => company.GetProperty("id").GetGuid() == _otherCompanyId);

            using var tenantSessionRequest = new HttpRequestMessage(HttpMethod.Get, "/api/session");
            tenantSessionRequest.Headers.Host = $"authorized-{additionalCompanyId:N}.envantertr.com";
            using var tenantSession = await authenticatedClient.SendAsync(tenantSessionRequest);
            Assert.Equal(HttpStatusCode.OK, tenantSession.StatusCode);
            using var tenantSessionPayload = JsonDocument.Parse(await tenantSession.Content.ReadAsStringAsync());
            var tenantCompanies = tenantSessionPayload.RootElement.GetProperty("availableCompanies").EnumerateArray().ToArray();
            Assert.Equal(2, tenantCompanies.Length);
            Assert.Contains(tenantCompanies, company => company.GetProperty("id").GetGuid() == _companyId);
            var selectedTenant = Assert.Single(tenantCompanies, company => company.GetProperty("id").GetGuid() == additionalCompanyId);
            Assert.Equal($"https://authorized-{additionalCompanyId:N}.envantertr.com/", selectedTenant.GetProperty("tenantUrl").GetString());
        }

        using var unrelatedChoice = await SendAnonymousLoginAsync(loginClient, email, password, null,
            requestToken, antiforgeryCookie, companyId: _otherCompanyId);
        Assert.Equal(HttpStatusCode.Forbidden, unrelatedChoice.StatusCode);

        using (var platformLogin = await SendAnonymousLoginAsync(loginClient, email, password, null,
            requestToken, antiforgeryCookie, platformAdminOnly: true))
        using (var platformSession = JsonDocument.Parse(await platformLogin.Content.ReadAsStringAsync()))
        {
            Assert.Equal(HttpStatusCode.OK, platformLogin.StatusCode);
            Assert.True(platformSession.RootElement.GetProperty("platformAdmin").GetBoolean());
            Assert.Equal(JsonValueKind.Null, platformSession.RootElement.GetProperty("companyId").ValueKind);
            Assert.Equal(JsonValueKind.Null, platformSession.RootElement.GetProperty("role").ValueKind);
        }

        using var wrongScopePlatformLogin = await SendAnonymousLoginAsync(loginClient, email, password, null,
            requestToken, antiforgeryCookie, platformAdminOnly: true,
            host: $"acceptance-{_companyId:N}.envantertr.com");
        Assert.Equal(HttpStatusCode.Forbidden, wrongScopePlatformLogin.StatusCode);

        var nonAdminEmail = $"acceptance-non-admin-{Guid.NewGuid():N}@example.invalid";
        await using (var nonAdminScope = _factory.Services.CreateAsyncScope())
        {
            var userManager = nonAdminScope.ServiceProvider.GetRequiredService<UserManager<EnvanterUser>>();
            var nonAdmin = new EnvanterUser
            {
                UserName = nonAdminEmail, Email = nonAdminEmail, EmailConfirmed = true,
                DisplayName = "Non-platform test user"
            };
            var create = await userManager.CreateAsync(nonAdmin, password);
            Assert.True(create.Succeeded, string.Join("; ", create.Errors.Select(error => error.Description)));
        }
        using var unauthorizedPlatformScope = await SendAnonymousLoginAsync(loginClient, nonAdminEmail, password, null,
            requestToken, antiforgeryCookie, platformAdminOnly: true);
        Assert.Equal(HttpStatusCode.Forbidden, unauthorizedPlatformScope.StatusCode);

        using (var tenantLogin = await SendAnonymousLoginAsync(loginClient, email, password, null,
            requestToken, antiforgeryCookie, companyId: null, host: $"acceptance-{_companyId:N}.envantertr.com"))
        using (var session = JsonDocument.Parse(await tenantLogin.Content.ReadAsStringAsync()))
        {
            Assert.Equal(HttpStatusCode.OK, tenantLogin.StatusCode);
            Assert.Equal(_companyId, session.RootElement.GetProperty("companyId").GetGuid());
        }

        using var wrongTenantChoice = await SendAnonymousLoginAsync(loginClient, email, password, null,
            requestToken, antiforgeryCookie, companyId: additionalCompanyId, host: $"acceptance-{_companyId:N}.envantertr.com");
        Assert.Equal(HttpStatusCode.Forbidden, wrongTenantChoice.StatusCode);
    }

